window.CATTO_INDICE = (window.CATTO_INDICE || []).concat([{"t":"Estructura de un sistema computacional","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/sistema-computacional","x":"Informática I · 120 h · Contenido 1 de 6 Estructura de un sistema computacional Antes de escribir una línea de código conviene saber sobre qué máquina se escribe: qué partes tiene, cómo busca y ejecuta cada instrucción, dónde guarda los datos y qué la hace rápida. Von Neumann Ciclo de instrucción Memoria Buses Rendimiento 01 Una computadora es una pila de máquinas Nadie programa una computadora «entera». Se programa la máquina que ofrece la capa de abajo. Quien escribe en C ve una máquina que entiende funciones y variables; el compilador la traduce a la máquina que entiende instrucciones; el procesador ejecuta cada instrucción con circuitos digitales, y esos circuitos son transistores que…"},{"t":"Sistemas de numeración y aritmética binaria","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/sistemas-numeracion","x":"Informática I · 120 h · Contenido 2 de 6 Sistemas de numeración y aritmética binaria Adentro de la máquina todo son bits. Lo que cambia es cómo se los lee: el mismo byte puede ser un número sin signo, uno negativo, un carácter o una instrucción. Binario Hexadecimal Complemento a dos Desborde IEEE 754 01 Un número no es su escritura Trece ovejas son trece ovejas, se escriban 13, XIII, 1101 o D. El número es la cantidad; lo que cambia es el sistema con que se anota. Los sistemas que usa la computación son posicionales: cada dígito pesa según el lugar que ocupa, y el peso de cada lugar es una potencia de la base b. n dígitos enteros y m fraccionarios. Con b = 10 es la cuenta de todos los días;…"},{"t":"Resolución de problemas y representación de algoritmos","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/algoritmos","x":"Informática I · 120 h · Contenido 3 de 6 Resolución de problemas y representación de algoritmos Programar es, sobre todo, resolver problemas. El lenguaje viene después: primero hay que entender qué se pide, planear la solución y poder explicarla sin ambigüedades. Algoritmo Pseudocódigo Diagrama de flujo Prueba de escritorio Eficiencia 01 Qué es un algoritmo Una receta de cocina, las instrucciones para armar un mueble y el procedimiento para medir una resistencia con un multímetro tienen algo en común: son pasos que, seguidos al pie de la letra, llevan a un resultado. Un algoritmo es eso mismo, con una exigencia más: tiene que poder seguirlo alguien que no entiende el problema, como una…"},{"t":"Lenguaje de programación estructurada","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/programacion-estructurada","x":"Informática I · 120 h · Contenido 4 de 6 Lenguaje de programación estructurada Tres estructuras de control, funciones que se entienden por separado y un compilador que traduce todo eso a instrucciones de máquina. C es el lenguaje donde esas dos cosas se ven a la vez. C Compilación Funciones Pila de llamadas Módulos 01 De los saltos a los bloques Los primeros programas se escribían con saltos: «si pasa tal cosa, ir a la línea 340». Funcionaban, pero a partir de cierto tamaño nadie podía seguir el hilo, porque a cualquier línea se podía llegar desde cualquier otra. En 1968 Edsger Dijkstra publicó una carta con un título que se volvió famoso, Go To Statement Considered Harmful: el salto libre…"},{"t":"Contenedores de datos complejos","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/datos-complejos","x":"Informática I · 120 h · Contenido 5 de 6 Contenedores de datos complejos La memoria es una fila de bytes numerados. Arreglos, matrices, estructuras y listas son maneras distintas de acomodar datos en esa fila y de saber dónde quedó cada uno. Arreglos Punteros Estructuras Memoria dinámica Archivos 01 Por qué agrupar datos Guardar las 1000 muestras de un osciloscopio en mil variables sueltas es imposible de manejar. Guardar una medición en tres variables sueltas —tensión, corriente e instante— obliga a pasarlas siempre juntas y a no mezclarlas nunca. Los contenedores de datos resuelven las dos cosas: el arreglo agrupa muchos datos del mismo tipo y la estructura agrupa datos distintos que…"},{"t":"Uso del lenguaje en aplicaciones de bajo nivel","d":"Tema · Informática I","u":"/publicaciones/mapa-ingenieria/temas/bajo-nivel","x":"Informática I · 120 h · Contenido 6 de 6 Uso del lenguaje en aplicaciones de bajo nivel El mismo C con el que se escribe un programa de escritorio maneja las patas de un microcontrolador: alcanza con los operadores de bits, un puntero a una dirección fija y saber por qué hace falta volatile. Operadores de bits Máscaras volatile stdint.h Interrupciones 01 Qué quiere decir «bajo nivel» Un programa de bajo nivel es el que habla directamente con el hardware: prende un LED escribiendo un bit en un registro, lee un sensor esperando que un bit de estado cambie, arma una trama bit por bit para mandarla por un cable. En la pila de capas del primer tema, es trabajar justo arriba de la arquitectura…"},{"t":"Matrices","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/matrices","x":"Álgebra y Geometría Analítica · 120 h · Contenido 1 de 9 Matrices Una matriz parece una tabla de números, pero es la forma más compacta de escribir un circuito entero, una rotación o el encadenamiento de dos etapas de un amplificador. Producto de matrices Inversa Rango Matriz de admitancias Cuadripolos 01 Una tabla que además opera Una matriz es un arreglo rectangular de números ordenados en filas y columnas. Hasta ahí es una tabla. Lo que la vuelve una herramienta es que sobre ese arreglo se definen operaciones —suma, producto, inversa— que representan cosas concretas: resolver un circuito, girar un vector, encadenar dos etapas de un amplificador. A es de orden m × n: m filas y n columnas.…"},{"t":"Determinantes","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/determinantes","x":"Álgebra y Geometría Analítica · 120 h · Contenido 2 de 9 Determinantes Un solo número resume si una matriz se puede invertir, si un sistema tiene solución única y cuánto agranda o achica las áreas la transformación asociada. Sarrus Cofactores Propiedades Cramer Interpretación geométrica 01 Un número que dice si el sistema se sostiene A cada matriz cuadrada se le puede asignar un número, su determinante, que resume una propiedad esencial: si vale cero, las filas son linealmente dependientes —alguna no aporta información nueva—, la matriz no tiene inversa y el sistema asociado o no tiene solución o tiene infinitas. Si no vale cero, todo lo contrario. Las tres lecturas del determinante…"},{"t":"Sistemas de ecuaciones lineales","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/sistemas-ecuaciones","x":"Álgebra y Geometría Analítica · 120 h · Contenido 3 de 9 Sistemas de ecuaciones lineales Resolver un circuito de tres mallas, ajustar una curva de calibración o simular una red entera son el mismo problema: A·x = b. Lo que cambia es el tamaño. Gauss-Jordan Rouché-Frobenius Sistemas homogéneos Pivoteo Análisis de mallas 01 De dónde salen los sistemas lineales Casi todo problema de ingeniería termina, en algún punto, en un sistema de ecuaciones lineales. Las leyes de Kirchhoff aplicadas a un circuito de n mallas dan n ecuaciones con n corrientes incógnitas. Un reticulado, un balance de materia, el ajuste por cuadrados mínimos de una curva de calibración y la simulación de cualquier circuito…"},{"t":"Vectores en R² y en R³","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/vectores-r2-r3","x":"Álgebra y Geometría Analítica · 120 h · Contenido 4 de 9 Vectores en R² y en R³ Fuerzas, campos, velocidades y fasores tienen algo en común: no alcanza un número para describirlos. Hace falta una dirección, y con ella aparece un álgebra propia. Componentes Producto escalar Producto vectorial Proyección Producto mixto 01 Cuando un número no alcanza La temperatura de un ambiente, la resistencia de un resistor o la energía de una batería quedan descriptas con un número y una unidad: son escalares. La fuerza sobre un electrón, el campo eléctrico en un punto o la velocidad de un móvil necesitan además una dirección y un sentido: son vectores. Un vector se representa con una flecha, pero lo que…"},{"t":"Recta y plano","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/recta-y-plano","x":"Álgebra y Geometría Analítica · 120 h · Contenido 5 de 9 Recta y plano Con un punto y una dirección queda definida una recta; con un punto y una normal, un plano. Todo lo demás son consecuencias de esas dos ideas. Ecuación vectorial Vector normal Distancias Ángulos Posiciones relativas 01 Dos datos alcanzan Toda la geometría analítica del espacio se apoya en dos ideas simples: Una recta Queda definida por un punto y una dirección. La dirección se da con un vector, llamado vector director. Un plano Queda definido por un punto y una perpendicular. Esa perpendicular se da con el vector normal. También hay otras maneras de fijarlos —dos puntos determinan una recta; tres puntos no alineados, un…"},{"t":"Formas cuadráticas y cónicas","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/formas-cuadraticas","x":"Álgebra y Geometría Analítica · 120 h · Contenido 6 de 9 Formas cuadráticas y cónicas La energía almacenada en un circuito, la potencia disipada y la elipse que dibuja una figura de Lissajous se escriben todas igual: como una forma cuadrática. Matriz asociada Cónicas Ejes principales Signo definido Energía 01 Polinomios de segundo grado, escritos con una matriz Una forma cuadrática es un polinomio homogéneo de segundo grado: todos sus términos tienen grado dos. En dos variables, q(x, y) = a x² + b xy + c y². Lo interesante es que se puede escribir con una matriz simétrica, repartiendo el término cruzado por mitades: La matriz se arma simétrica a propósito: así sus autovalores son reales y…"},{"t":"Espacios vectoriales","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/espacios-vectoriales","x":"Álgebra y Geometría Analítica · 120 h · Contenido 7 de 9 Espacios vectoriales Las señales, los polinomios y las matrices se suman y se escalan con las mismas reglas que las flechas del plano. Esa estructura común es lo que se estudia acá. Subespacios Independencia lineal Base Dimensión Cambio de base 01 La misma estructura en cosas muy distintas Las flechas del plano se suman y se multiplican por números. Las matrices de 2 × 3, también. Y los polinomios de grado menor o igual que 3. Y las señales de tensión en función del tiempo. En los cuatro casos valen las mismas reglas, así que conviene estudiarlas una sola vez: eso es un espacio vectorial. Formalmente, un conjunto V con una suma y un…"},{"t":"Transformaciones lineales","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/transformaciones-lineales","x":"Álgebra y Geometría Analítica · 120 h · Contenido 8 de 9 Transformaciones lineales Una función que respeta la suma y el producto por escalares queda determinada por lo que le hace a una base, y eso cabe en una matriz. Matriz asociada Núcleo Imagen Teorema de la dimensión Composición 01 Funciones que respetan la estructura Una transformación lineal es una función entre espacios vectoriales que se lleva bien con las dos operaciones: Las dos condiciones juntas se resumen en una: T(a·u + b·v) = a·T(u) + b·T(v). Es el principio de superposición. De la segunda condición, con k = 0, sale que T(0) = 0: toda transformación lineal manda el vector nulo al vector nulo. Eso descarta de entrada a f(x) =…"},{"t":"Autovalores y autovectores","d":"Tema · Álgebra y Geometría Analítica","u":"/publicaciones/mapa-ingenieria/temas/autovalores-autovectores","x":"Álgebra y Geometría Analítica · 120 h · Contenido 9 de 9 Autovalores y autovectores En toda transformación hay direcciones privilegiadas que no se desvían, sólo se estiran. Encontrarlas es encontrar los modos propios de un sistema físico. Polinomio característico Diagonalización Modos naturales Estabilidad Resonancia 01 Direcciones que no se desvían Una transformación lineal, en general, mueve cada vector y le cambia la dirección. Pero casi siempre hay unas pocas direcciones privilegiadas en las que el vector no se desvía: sólo se estira, se acorta o se da vuelta. Esas direcciones son los autovectores, y el factor por el que se estiran, los autovalores. El vector nulo se excluye a…"},{"t":"Funciones de una variable real","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/funciones-variable-real","x":"Análisis Matemático I · 120 h · Contenido 1 de 10 Funciones de una variable real Una función es una regla que a cada entrada le asigna una única salida. Con esa idea se describen la característica de un diodo, la ganancia de un amplificador y cualquier señal en el tiempo. Dominio e imagen Composición Inversa Transformaciones Transferencia 01 Una entrada, una sola salida Una función de una variable real es una regla que a cada número de un conjunto de partida le asigna uno y sólo un número del conjunto de llegada. Esa unicidad es toda la definición, y es lo que la hace útil en ingeniería: si el circuito es una función de la entrada, para cada entrada hay una salida bien determinada. Nombre…"},{"t":"Límite de funciones reales","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/limite-funciones","x":"Análisis Matemático I · 120 h · Contenido 2 de 10 Límite de funciones reales El límite pregunta a qué valor se acerca una función cerca de un punto, sin importar lo que pase exactamente en él. De esa distinción salen la derivada, la integral y el régimen permanente. Épsilon y delta Laterales Indeterminaciones Límites notables Asíntotas 01 Qué pasa cerca, no qué pasa en el punto El límite responde una pregunta muy precisa: a qué valor se acerca f(x) cuando x se acerca a un número a, sin llegar nunca a él. Lo que ocurra exactamente en x = a no interviene; la función puede incluso no estar definida ahí. El ejemplo que fija la idea f(x) = (x² − 1)/(x − 1) no existe en x = 1: da 0/0. Pero para…"},{"t":"Funciones continuas","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/funciones-continuas","x":"Análisis Matemático I · 120 h · Contenido 3 de 10 Funciones continuas Que una función sea continua no es un detalle técnico: es lo que permite asegurar que existe una raíz, que hay un máximo y que la tensión de un capacitor no puede dar saltos. Discontinuidades Bolzano Valor intermedio Weierstrass Bisección 01 Tres condiciones, no una Una función es continua en un punto a cuando se cumplen las tres cosas a la vez: Que exista el valor, que exista el límite y que coincidan. Si falla cualquiera de las tres, hay discontinuidad. La imagen intuitiva —«se dibuja sin levantar el lápiz»— sirve para empezar, pero es imprecisa: hay funciones continuas imposibles de dibujar. La definición de arriba es…"},{"t":"Funciones diferenciables","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/derivada","x":"Análisis Matemático I · 120 h · Contenido 4 de 10 Funciones diferenciables La derivada mide cuán rápido cambia algo. En un circuito es la corriente de un capacitor, la tensión de una bobina y la velocidad de respuesta de un amplificador. Cociente incremental Recta tangente Reglas Regla de la cadena Diferencial 01 La pendiente en un punto La pendiente de una recta se calcula con dos puntos. ¿Y la de una curva, en un solo punto? La salida es tomar dos puntos muy cercanos, calcular la pendiente de la recta que los une —la secante— y ver a qué valor tiende cuando los puntos se juntan. Ese límite es la derivada: El cociente incremental Δy/Δx es la pendiente de la secante. Su límite, cuando…"},{"t":"Aplicaciones de la derivada","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/aplicaciones-derivada","x":"Análisis Matemático I · 120 h · Contenido 5 de 10 Aplicaciones de la derivada Con la derivada se encuentran los máximos y los mínimos, se justifican las aproximaciones lineales y se resuelven los problemas de optimización que aparecen en todo diseño. Extremos Concavidad Lagrange L'Hôpital Taylor 01 Crecimiento y extremos El signo de la derivada dice hacia dónde va la función, y los puntos donde se anula son los candidatos a máximo o mínimo: Si en un intervalo… entonces f… f′(x) > 0 crece f′(x) < 0 decrece f′(c) = 0 o no existe tiene un punto crítico en c: hay que analizarlo El criterio de la primera derivada resuelve cada punto crítico mirando cómo cambia el signo de f′ al pasar por él: de…"},{"t":"Cálculo integral","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/calculo-integral","x":"Análisis Matemático I · 120 h · Contenido 6 de 10 Cálculo integral Integrar es la operación inversa de derivar: a partir de cómo cambia algo, reconstruir cuánto vale. Primitivas Sustitución Por partes Fracciones simples Tabla 01 Deshacer la derivada Derivar es fácil y mecánico: hay reglas para todo. La operación inversa —dada la derivada, encontrar la función— se llama hallar una primitiva, y no es mecánica: es un oficio. La constante de integración no es un adorno: como la derivada de una constante es cero, hay infinitas primitivas, todas paralelas entre sí. Que todas las primitivas de una función difieran sólo en una constante es una consecuencia directa del teorema de Lagrange : si dos…"},{"t":"La integral definida","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/integral-definida","x":"Análisis Matemático I · 120 h · Contenido 7 de 10 La integral definida La integral definida es un área, y un área es una suma de infinitos rectángulos infinitamente finos. De ahí salen el valor medio y el valor eficaz de cualquier señal. Sumas de Riemann Área Valor medio Valor eficaz Propiedades 01 Un área que se arma con rectángulos ¿Cuánta carga entregó una corriente que fue variando? ¿Cuánta energía disipó un resistor? Las dos preguntas son la misma: el área bajo una curva. Y el área bajo una curva cualquiera no tiene fórmula, así que se la construye: se parte el intervalo en n pedacitos, se levanta un rectángulo sobre cada uno y se suman. Es la suma de Riemann. Cuantos más rectángulos,…"},{"t":"El teorema fundamental del cálculo","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/teorema-fundamental","x":"Análisis Matemático I · 120 h · Contenido 8 de 10 El teorema fundamental del cálculo Derivar e integrar son operaciones inversas. Ese resultado, que parece evidente, es el teorema que unifica todo el cálculo y el que permite calcular áreas sin sumar infinitos términos. Función área Regla de Barrow Primitiva Derivada e integral Aplicaciones 01 La función área Hasta acá la integral definida daba un número. Pero si se deja fijo el extremo de abajo y se mueve el de arriba, aparece una función: la que acumula área a medida que avanza. La variable de integración se llama t para no confundirla con el límite superior x. A(a) = 0, y A crece donde f es positiva. Esta función es exactamente la carga…"},{"t":"Aplicaciones de la integral definida","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/aplicaciones-integral","x":"Análisis Matemático I · 120 h · Contenido 9 de 10 Aplicaciones de la integral definida Con integrales definidas se calculan áreas, volúmenes, trabajo, carga acumulada y la energía que entrega una señal a una carga. Áreas Volúmenes Trabajo Energía Valor eficaz 01 Áreas entre curvas El área encerrada entre dos curvas es la integral de la diferencia, la de arriba menos la de abajo, entre los puntos donde se cortan: Los límites a y b salen de resolver f(x) = g(x). Si las curvas se cruzan adentro del intervalo, hay que partirlo y cambiar el orden de la resta en cada tramo. Ejemplo resuelto Entre y = x y y = x²: se cortan en x = 0 y x = 1, y en ese tramo la recta va por arriba. A = ∫₀¹ (x − x²)…"},{"t":"Series","d":"Tema · Análisis Matemático I","u":"/publicaciones/mapa-ingenieria/temas/series","x":"Análisis Matemático I · 120 h · Contenido 10 de 10 Series Sumar infinitos términos puede dar un número finito. Esa idea permite representar funciones como polinomios infinitos y señales como sumas de senoidales. Convergencia Criterios Series de potencias Taylor Fourier 01 Primero, sucesiones Una sucesión es una lista infinita y ordenada de números: a₁, a₂, a₃, … Lo único que interesa de ella es su comportamiento a la larga: si se acerca a un número —converge— o no. Sucesión Comportamiento Dónde aparece an = 1/n Converge a 0 Error de un método numérico an = rn Converge a 0 si |r| < 1; diverge si |r| > 1 Amplitud de cada rebote de una señal en una línea desadaptada an = (−1)n Oscila: no…"},{"t":"Conocimiento científico y tecnológico","d":"Tema · Ingeniería y Sociedad","u":"/publicaciones/mapa-ingenieria/temas/conocimiento-cientifico-tecnologico","x":"Ingeniería y Sociedad · 48 h · Contenido 1 de 5 Conocimiento científico y tecnológico Ciencia, técnica y tecnología no son sinónimos. Distinguirlas cambia qué se le puede exigir a cada una, y explica por qué un ingeniero tiene que decidir aunque no tenga toda la información. Ciencia y técnica Falsabilidad Paradigmas Conocimiento tecnológico TRL 01 Ciencia, técnica, tecnología e ingeniería Se usan como sinónimos y no lo son. Distinguirlas no es un capricho académico: cambia qué se le puede exigir a cada una y qué preguntas responde. Actividad Qué busca Cómo se valida Ejemplo en electrónica Ciencia Explicar: conocimiento verdadero sobre cómo es el mundo Contrastando predicciones con la…"},{"t":"Tecnología, industria y desarrollo sostenible","d":"Tema · Ingeniería y Sociedad","u":"/publicaciones/mapa-ingenieria/temas/desarrollo-sostenible","x":"Ingeniería y Sociedad · 48 h · Contenido 2 de 5 Tecnología, industria y desarrollo sostenible En un teléfono, casi toda la huella ambiental ya ocurrió antes de encenderlo. Saber dónde está el impacto de verdad es lo que permite decidir bien en el tablero de diseño. Brundtland Ciclo de vida RAEE Eficiencia Economía circular 01 Qué se quiso decir con «desarrollo sostenible» La definición que se volvió estándar es de 1987, del informe Nuestro futuro común de la Comisión Mundial sobre Medio Ambiente y Desarrollo, conocido como informe Brundtland: La definición de Brundtland Desarrollo sostenible es «el desarrollo que satisface las necesidades del presente sin comprometer la capacidad de las…"},{"t":"Dimensión e impacto social de la ingeniería","d":"Tema · Ingeniería y Sociedad","u":"/publicaciones/mapa-ingenieria/temas/impacto-social","x":"Ingeniería y Sociedad · 48 h · Contenido 3 de 5 Dimensión e impacto social de la ingeniería Las decisiones de diseño reparten costos, beneficios y posibilidades antes de que nadie use el producto. Por eso el que diseña no es un ejecutor neutral. Winner Primer y segundo orden Evaluación de tecnologías Riesgo Accesibilidad 01 Ningún artefacto es socialmente neutro Una idea cómoda dice que la tecnología es una herramienta neutral y que todo depende del uso que se le dé. Es parcialmente cierta y, tomada al pie de la letra, falsa: las decisiones de diseño reparten posibilidades. Un equipo que sólo se puede reparar en el servicio oficial, una plataforma que decide qué contenido se ve primero o…"},{"t":"Políticas para el desarrollo nacional y regional","d":"Tema · Ingeniería y Sociedad","u":"/publicaciones/mapa-ingenieria/temas/politicas-desarrollo","x":"Ingeniería y Sociedad · 48 h · Contenido 4 de 5 Políticas para el desarrollo nacional y regional Que un país diseñe o sólo ensamble no es una consecuencia natural de nada: es el resultado de decisiones de política que se pueden estudiar. Triángulo de Sábato Innovación Industria local Financiamiento Caso argentino 01 Por qué hay política tecnológica Ningún país compra desarrollo en una góndola. Lo que se puede comprar son productos; la capacidad de diseñarlos, mantenerlos y mejorarlos se construye, y esa construcción lleva décadas y decisiones. La política tecnológica es el conjunto de decisiones públicas sobre qué se investiga, qué se produce localmente, qué se importa y quién paga la…"},{"t":"La profesión en la Argentina y la ética profesional","d":"Tema · Ingeniería y Sociedad","u":"/publicaciones/mapa-ingenieria/temas/profesion-etica","x":"Ingeniería y Sociedad · 48 h · Contenido 5 de 5 La profesión en la Argentina y la ética profesional Firmar un plano o un informe compromete la responsabilidad personal de quien firma. Todo lo demás —matrícula, incumbencias, código de ética— se entiende a partir de ahí. Incumbencias Matrícula Responsabilidad Código de ética Géneros 01 Qué habilita el título, y qué no El título universitario acredita una formación. Lo que habilita a ejercer es la matrícula, que otorgan y controlan los consejos profesionales. En electrónica y telecomunicaciones, a nivel nacional, el organismo es el COPITEC, Consejo Profesional de Ingeniería de Telecomunicaciones, Electrónica y Computación; en las provincias…"},{"t":"Funciones vectoriales de una variable real","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/funciones-vectoriales","x":"Análisis Matemático II · 120 h · Contenido 1 de 8 Funciones vectoriales de una variable real Cuando una función devuelve un vector en lugar de un número, describe un movimiento. Derivarla da la velocidad; derivar otra vez, la aceleración, y de ahí sale casi toda la cinemática. Curvas paramétricas Vector tangente Longitud de arco Curvatura Frenet 01 Una función que devuelve un vector Hasta ahora las funciones tomaban un número y devolvían un número. Una función vectorial de una variable real toma un número —típicamente el tiempo— y devuelve un vector: la posición de algo que se mueve. Cada componente es una función común. Al variar t, la punta del vector describe una curva, y t es su…"},{"t":"Funciones escalares de varias variables","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/funciones-varias-variables","x":"Análisis Matemático II · 120 h · Contenido 2 de 8 Funciones escalares de varias variables La temperatura de una placa, el potencial alrededor de dos cargas o la ganancia de un amplificador en función de dos componentes: todas son funciones de varias variables. Dominio Curvas de nivel Superficies Límites Continuidad 01 Una salida, varias entradas La temperatura de una placa depende de dónde se la mida: T(x, y). La potencia disipada por un resistor depende de la tensión y de la resistencia: P(V, R). La ganancia de una etapa depende de dos componentes. Todas son funciones escalares de varias variables: entran dos o más números, sale uno. Con dos variables el gráfico es una superficie en el…"},{"t":"Cálculo diferencial de varias variables","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/calculo-diferencial-varias","x":"Análisis Matemático II · 120 h · Contenido 3 de 8 Cálculo diferencial de varias variables Con varias variables, la derivada se vuelve un vector: el gradiente, que apunta hacia donde la función crece más rápido y es perpendicular a las curvas de nivel. Derivadas parciales Gradiente Plano tangente Extremos Lagrange 01 Derivadas parciales: mover una variable por vez Con varias variables, «la» derivada no alcanza: hay que decir respecto de cuál. La derivada parcial se calcula dejando las demás fijas, como si fueran constantes: Geométricamente: se corta la superficie con el plano y = cte y se mide la pendiente de la curva que queda. Lo que significa en el laboratorio Una derivada parcial es una…"},{"t":"Ecuaciones diferenciales ordinarias","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/ecuaciones-diferenciales","x":"Análisis Matemático II · 120 h · Contenido 4 de 8 Ecuaciones diferenciales ordinarias Un circuito con un capacitor o una bobina no se describe con una ecuación algebraica sino con una diferencial. Resolverla es predecir cómo evoluciona en el tiempo. Primer orden Segundo orden Régimen libre Forzado RLC 01 Ecuaciones donde la incógnita es una función Una ecuación diferencial relaciona una función con sus derivadas. Su incógnita no es un número: es la función entera. Aparecen apenas algo cambia en el tiempo, y en electrónica aparecen en cuanto hay un capacitor o una bobina, porque sus leyes ya son derivadas. A la izquierda, un circuito RC: ecuación de primer orden. A la derecha, un RLC serie:…"},{"t":"Integrales dobles y triples","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/integrales-multiples","x":"Análisis Matemático II · 120 h · Contenido 5 de 8 Integrales dobles y triples Integrar en más de una variable es sumar sobre una región del plano o del espacio: áreas, volúmenes, masas y cargas distribuidas. Integral doble Orden de integración Polares Cilíndricas Centro de masa 01 Sumar sobre una región La integral simple sumaba sobre un intervalo. La integral doble suma sobre una región del plano: se parte la región en rectangulitos, se evalúa la función en cada uno, se multiplica por su área y se suman todos. Si f ≥ 0, el resultado es el volumen bajo la superficie sobre esa región. Con f = 1, es el área de la región. Igual que antes, nadie calcula el límite: se lo convierte en dos…"},{"t":"Campos vectoriales, rotacional y divergencia","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/campos-vectoriales","x":"Análisis Matemático II · 120 h · Contenido 6 de 8 Campos vectoriales, rotacional y divergencia Un campo asigna un vector a cada punto del espacio. La divergencia mide si hay fuentes y el rotacional, si hay circulación: las dos preguntas centrales del electromagnetismo. Líneas de campo Divergencia Rotacional Conservativos Potencial 01 Un vector en cada punto Un campo vectorial asigna un vector a cada punto del espacio. No es una curva ni una superficie: es una distribución. El viento en un mapa, la velocidad del agua en un río, el campo eléctrico alrededor de una carga y el campo magnético dentro de un transformador son campos vectoriales. Cada componente es una función escalar de tres…"},{"t":"Integrales de línea y de superficie","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/integrales-linea-superficie","x":"Análisis Matemático II · 120 h · Contenido 7 de 8 Integrales de línea y de superficie El trabajo de una fuerza a lo largo de un camino y el flujo de un campo a través de una superficie son las dos integrales con las que se escribe el electromagnetismo. Circulación Trabajo Independencia del camino Flujo Superficies 01 Integrar a lo largo de una curva Hasta ahora se integraba sobre intervalos y sobre regiones. Ahora el dominio es una curva. Si lo que se integra es un campo escalar —una densidad, por ejemplo—, la integral de línea da la cantidad total a lo largo del alambre: El factor |r′(t)| convierte el paso del parámetro en longitud real: es el mismo de la longitud de arco. Con f = 1 se…"},{"t":"Teoremas del cálculo vectorial","d":"Tema · Análisis Matemático II","u":"/publicaciones/mapa-ingenieria/temas/teoremas-calculo-vectorial","x":"Análisis Matemático II · 120 h · Contenido 8 de 8 Teoremas del cálculo vectorial Green, Gauss y Stokes dicen lo mismo en distintas dimensiones: lo que pasa adentro de una región queda determinado por lo que ocurre en su borde. De ahí salen las ecuaciones de Maxwell. Green Divergencia Stokes Maxwell Forma integral 01 Una sola idea, tres enunciados Los tres teoremas que cierran el cálculo vectorial dicen lo mismo con vestimentas distintas: lo que pasa en el borde queda determinado por lo que pasa adentro. Es la misma estructura de la regla de Barrow, pero con una dimensión más cada vez. Teorema Borde Interior Barrow : dos puntos Green Stokes Divergencia (Gauss) La consecuencia práctica Cuando…"},{"t":"Cinemática del punto material","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/cinematica-punto","x":"Física I · 120 h · Contenido 1 de 10 Cinemática del punto material La cinemática describe el movimiento sin preguntarse por sus causas. Son tres funciones del tiempo —posición, velocidad y aceleración— ligadas por una derivada, y esa misma estructura reaparece después en la carga de un capacitor. Posición Velocidad Aceleración Tiro oblicuo Movimiento circular 01 Describir un movimiento Antes de preguntarse por qué algo se mueve hay que poder decir cómo se mueve. Para eso hacen falta tres decisiones previas, que casi siempre se toman sin darse cuenta: Un sistema de referencia. No existe el movimiento absoluto: un pasajero sentado está quieto respecto del colectivo y a 60 km/h respecto de la…"},{"t":"Dinámica del punto material","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/dinamica-punto","x":"Física I · 120 h · Contenido 2 de 10 Dinámica del punto material Newton no dice qué es una fuerza: dice qué hace. Y lo que hace es cambiar la velocidad. Todo el oficio está en dibujar bien el diagrama de cuerpo libre antes de escribir una sola ecuación. Leyes de Newton Cuerpo libre Rozamiento Plano inclinado Sistemas 01 Las tres leyes, dichas con precisión Primera ley · principio de inercia Un cuerpo sobre el que la fuerza neta es nula conserva su velocidad: si estaba quieto sigue quieto, y si se movía sigue moviéndose en línea recta y con rapidez constante. Lo que hace falta explicar no es el movimiento, sino el cambio de movimiento. La primera ley también define en qué sistemas valen las…"},{"t":"Leyes de conservación en mecánica","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/conservacion-mecanica","x":"Física I · 120 h · Contenido 3 de 10 Leyes de conservación en mecánica Hay cantidades que no cambian aunque todo lo demás cambie. Esas constantes permiten resolver en dos renglones problemas que por Newton llevarían una página entera de ecuaciones diferenciales. Trabajo Energía mecánica Cantidad de movimiento Impulso Choques 01 Por qué conviene conservar algo Resolver un problema por Newton exige conocer las fuerzas en cada instante. Muchas veces no se las conoce —¿qué fuerza exacta hacen dos autos durante el choque?— y aun así se puede responder, porque ciertas cantidades valen lo mismo antes y después sin importar lo que haya pasado en el medio. Las tres del programa Energía mecánica, si…"},{"t":"Cinemática y dinámica del cuerpo rígido","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/cinematica-dinamica-rigido","x":"Física I · 120 h · Contenido 4 de 10 Cinemática y dinámica del cuerpo rígido Un cuerpo extenso no sólo se traslada: también gira. Cada magnitud de la traslación tiene su gemela en la rotación, y la masa se convierte en momento de inercia. Rotación Momento de inercia Torque Rodadura Momento angular 01 Cada magnitud tiene su gemela Un cuerpo rígido es un modelo: un sólido cuyas partículas mantienen siempre la misma distancia entre sí. No se deforma. Con esa idealización, todo el movimiento se descompone en traslación del centro de masa más rotación alrededor de él. Y lo notable es que la rotación repite, término por término, la estructura de la traslación: Traslación Rotación Relación…"},{"t":"Estática","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/estatica","x":"Física I · 120 h · Contenido 5 de 10 Estática Que algo no se mueva no significa que no haya fuerzas: significa que se cancelan. Dos ecuaciones vectoriales sostienen puentes, estanterías y el soporte de una antena. Equilibrio Momentos Centro de gravedad Vínculos Reticulados 01 Las dos condiciones del equilibrio Que un cuerpo no se mueva no significa que no haya fuerzas: significa que se cancelan. Y para un cuerpo extenso no alcanza con que se cancelen las fuerzas, porque un par de fuerzas iguales y opuestas aplicadas en puntos distintos lo hacen girar. Hacen falta dos condiciones: Equilibrio de traslación y equilibrio de rotación. En el plano son tres ecuaciones escalares: ΣFx, ΣFy y ΣM. El…"},{"t":"Movimiento oscilatorio","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/movimiento-oscilatorio","x":"Física I · 120 h · Contenido 6 de 10 Movimiento oscilatorio El resorte que oscila y el circuito RLC obedecen la misma ecuación diferencial. Quien entiende uno entiende el otro, y la resonancia mecánica es literalmente la del sintonizador de una radio. Armónico simple Péndulo Amortiguamiento Resonancia Factor Q 01 Movimiento armónico simple Siempre que una fuerza de restitución sea proporcional al apartamiento y apunte en sentido contrario, el movimiento que resulta es armónico simple. La ley de Hooke, F = −k·x, llevada a la segunda ley da: La frecuencia propia no depende de la amplitud: por eso un péndulo sirve como reloj. Sistema Frecuencia angular propia Condición Masa y resorte Resorte…"},{"t":"Ondas mecánicas","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/ondas-mecanicas","x":"Física I · 120 h · Contenido 7 de 10 Ondas mecánicas Una onda transporta energía sin transportar materia. La cuerda con un extremo fijo y la línea de transmisión terminada en cortocircuito producen exactamente la misma onda estacionaria. Ecuación de onda Estacionarias Interferencia Sonido Doppler 01 Qué es una onda Una onda transporta energía y cantidad de movimiento sin transportar materia. Cada partícula del medio oscila alrededor de su posición de equilibrio, y lo que viaja es la perturbación. Transversal: las partículas oscilan perpendicularmente a la dirección de propagación. Una cuerda, una onda electromagnética. Longitudinal: oscilan en la misma dirección en la que avanza la onda. El…"},{"t":"Fluidos en equilibrio","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/fluidos-equilibrio","x":"Física I · 120 h · Contenido 8 de 10 Fluidos en equilibrio La presión en un fluido en reposo sólo depende de la profundidad. De ahí salen la prensa hidráulica, el flotador y la medición de presión con una columna de mercurio. Presión Pascal Hidrostática Arquímedes Manómetros 01 Presión Un fluido en reposo no puede sostener esfuerzos de corte: sólo ejerce fuerzas perpendiculares a cualquier superficie que toque. Esa fuerza por unidad de área es la presión, y es un escalar: en un punto vale lo mismo en todas las direcciones. Unidad Equivale a Dónde se usa 1 Pa 1 N/m² Unidad del sistema internacional 1 bar 10⁵ Pa Neumática e industria 1 atm Presión atmosférica normal 1 mmHg (torr) 133,3 Pa…"},{"t":"Dinámica de fluidos","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/dinamica-fluidos","x":"Física I · 120 h · Contenido 9 de 10 Dinámica de fluidos El caudal que entra es el que sale, y donde el fluido se acelera la presión baja. Con esas dos ideas se explican el ala de un avión, el caudalímetro y el ventilador de un disipador. Caudal Continuidad Bernoulli Viscosidad Reynolds 01 Caudal y continuidad El caudal es el volumen que pasa por una sección en cada unidad de tiempo, Q = A·v, en m³/s. Si el fluido es incompresible y no hay fugas, lo que entra por un extremo sale por el otro: Donde el tubo se angosta, el fluido se acelera. Es la razón de que al tapar parte de la boca de una manguera el chorro salga más rápido. La misma ecuación, en un circuito La ecuación de continuidad es…"},{"t":"Óptica geométrica","d":"Tema · Física I","u":"/publicaciones/mapa-ingenieria/temas/optica-geometrica","x":"Física I · 120 h · Contenido 10 de 10 Óptica geométrica Cuando la longitud de onda es mucho menor que los objetos, la luz se puede tratar como rayos que viajan en línea recta. Sobre esa aproximación se construyen la lente, el sensor de imagen y la fibra óptica. Reflexión Ley de Snell Reflexión total Lentes Fibra óptica 01 Cuándo la luz se puede tratar como rayos La luz es una onda electromagnética, pero cuando los objetos que encuentra son mucho más grandes que su longitud de onda —medio micrómetro para la luz visible— se comporta como si viajara en rayos rectilíneos. Esa aproximación es la óptica geométrica, y con ella se diseñan lentes, espejos, cámaras y fibras. Cuando esa condición no…"},{"t":"Sistemas de representación","d":"Tema · Diseño asistido por computadora","u":"/publicaciones/mapa-ingenieria/temas/sistemas-representacion","x":"Diseño asistido por computadora · 72 h · Contenido 1 de 5 Sistemas de representación Un plano es un idioma: convierte un objeto de tres dimensiones en figuras planas que cualquier taller del mundo puede volver a convertir en el objeto. Lo primero es aprender a proyectar. Proyección ortogonal Vistas Primer diedro Tercer diedro Isométrica 01 Proyectar Representar un objeto de tres dimensiones sobre un papel exige elegir cómo proyectarlo. Las dos familias que importan en ingeniería son: Sistema Cómo proyecta Para qué sirve Proyección ortogonal (vistas) Rayos paralelos y perpendiculares al plano Fabricar: conserva las medidas verdaderas Axonometría (isométrica) Rayos paralelos, oblicuos al…"},{"t":"Normas nacionales e internacionales","d":"Tema · Diseño asistido por computadora","u":"/publicaciones/mapa-ingenieria/temas/normas-dibujo","x":"Diseño asistido por computadora · 72 h · Contenido 2 de 5 Normas nacionales e internacionales Las normas evitan que cada uno dibuje como quiera. Un plano normalizado se entiende igual en Rosario que en Shenzhen, y eso es exactamente lo que se necesita para fabricar. IRAM ISO Formatos Escalas Rótulo 01 Para qué sirve normalizar Una norma es un acuerdo escrito sobre cómo se hacen las cosas. En dibujo técnico eso significa que el plano que sale de una oficina de Rosario se fabrica sin llamadas telefónicas en un taller de Shenzhen, porque los dos leen lo mismo. Organismo Alcance Ejemplos IRAM Argentina IRAM 4504 formatos, 4501 líneas, 4513 acotación ISO Internacional ISO 216 formatos, ISO 128…"},{"t":"Normas de representación de circuitos","d":"Tema · Diseño asistido por computadora","u":"/publicaciones/mapa-ingenieria/temas/normas-circuitos","x":"Diseño asistido por computadora · 72 h · Contenido 3 de 5 Normas de representación de circuitos Un esquema no es un dibujo del circuito: es un mapa de sus conexiones. Los símbolos están normalizados justamente para que la topología se lea de un vistazo. Símbolos Referencias Unifilar Multifilar Esquemas 01 Un esquema no es un dibujo del circuito La foto de una placa muestra dónde está cada componente; el esquema muestra cómo están conectados. Son dos documentos distintos y los dos hacen falta, pero para entender qué hace un circuito sirve el segundo. Documento Qué muestra Para qué se usa Esquema funcional Conexiones lógicas, sin posiciones reales Entender, analizar, reparar Esquema…"},{"t":"Croquizado de circuitos","d":"Tema · Diseño asistido por computadora","u":"/publicaciones/mapa-ingenieria/temas/croquizado-circuitos","x":"Diseño asistido por computadora · 72 h · Contenido 4 de 5 Croquizado de circuitos Antes del programa está el lápiz. Un croquis claro resuelve la mitad de los problemas de un diseño, y enseña a pensar el circuito por bloques antes de dibujar un solo cable. Croquis Proporción Bloques Conexiones Legibilidad 01 Por qué croquizar antes de abrir el programa Un croquis es un dibujo a mano alzada, proporcionado pero no a escala, hecho para pensar. No compite con el plano de CAD: viene antes. Es más rápido: se prueban tres disposiciones en el tiempo que lleva ubicar un símbolo en la computadora. Obliga a decidir la estructura —qué bloques hay y cómo se enlazan— antes de perderse en los detalles.…"},{"t":"Entornos de diseño asistido","d":"Tema · Diseño asistido por computadora","u":"/publicaciones/mapa-ingenieria/temas/diseno-asistido","x":"Diseño asistido por computadora · 72 h · Contenido 5 de 5 Entornos de diseño asistido El programa no dibuja por uno: acelera lo que uno ya sabe hacer. Lo que cambia con el CAD es que el dibujo pasa a ser un modelo con datos, y de ahí sale la lista de materiales y la placa. CAD EDA Capas Netlist PCB 01 Qué cambia cuando el dibujo pasa a ser un modelo Un plano en papel es un conjunto de líneas: el significado lo pone quien lo lee. Un dibujo de CAD es una base de datos: el programa sabe que ese rectángulo es un resistor de 470 Ω, que está conectado a ese nodo y que su encapsulado mide tanto. De esa diferencia salen todas las ventajas. Sobre el papel En CAD o EDA Se redibuja para cambiar una…"},{"t":"Programación avanzada en C","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/programacion-avanzada","x":"Informática II · 120 h · Contenido 1 de 8 Programación avanzada en C En C se programa sabiendo dónde están las cosas. El puntero no es una rareza del lenguaje: es la dirección de memoria, y entenderlo es la diferencia entre pelearse con el compilador y manejar el hardware. Punteros Direcciones Arreglos malloc Modularización 01 Toda variable tiene una dirección Una variable es un nombre para un lugar de la memoria. Ese lugar tiene una dirección, y C permite trabajar con ella directamente, algo que la mayoría de los lenguajes esconde. Operador Se lee Qué devuelve &x dirección de x Dónde está guardada x *p contenido de p El valor que hay en la dirección que guarda p int *p; p es puntero a int…"},{"t":"Estructuras dinámicas de datos","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/estructuras-dinamicas","x":"Informática II · 120 h · Contenido 2 de 8 Estructuras dinámicas de datos Cuando no se sabe de antemano cuántos datos van a llegar, el arreglo estorba. La lista enlazada crece y se achica siguiendo punteros, y con ese mecanismo se construyen colas, pilas y árboles. Lista enlazada Nodos Pila Cola Árbol binario 01 Cuando el arreglo no alcanza Un arreglo es rápido y simple, pero tiene un tamaño fijo decidido antes de correr el programa. Si llegan más datos de los previstos, se desborda; si llegan menos, se desperdicia memoria. Una estructura dinámica crece y se achica durante la ejecución, reservando un nodo por dato. Operación Arreglo Lista enlazada Acceder al elemento i O(1): cuenta directa…"},{"t":"Herramientas de construcción de software","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/construccion-software","x":"Informática II · 120 h · Contenido 3 de 8 Herramientas de construcción de software Entre el archivo de texto y el programa que corre hay cuatro etapas, y cada una tira sus propios errores. Saber cuál falló ahorra la mitad del tiempo de depuración. Preprocesador Compilador Enlazador make git 01 Las cuatro etapas Escribir gcc main.c -o programa parece un solo paso, pero son cuatro programas encadenados. Saber cuál falló es la mitad de la depuración: Etapa Entra Sale Error típico Preprocesador .c .i No encuentra un encabezado Compilador .i .s (ensamblador) Error de sintaxis o de tipos Ensamblador .s .o (objeto) Rara vez falla Enlazador .o y bibliotecas Ejecutable Referencia indefinida Cómo…"},{"t":"Control de periféricos y comunicación","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/control-perifericos","x":"Informática II · 120 h · Contenido 4 de 8 Control de periféricos y comunicación El programa deja de ser un ejercicio cuando enciende un LED real. Del otro lado del cable hay un microcontrolador esperando bytes, y hay que ponerse de acuerdo en qué significa cada uno. Puerto serie Tramas Checksum Buffers Protocolo 01 Del programa al mundo físico Un programa que sólo imprime en pantalla no necesita saber nada del hardware. Apenas hay que encender un LED o leer un sensor, aparecen tres preguntas: por dónde salen los datos, con qué velocidad y qué significa cada byte. Interfaz Velocidad típica Dónde se usa Serie asincrónica (UART/USB-serie) 9600 a 921 600 baudios Lo más común entre PC y…"},{"t":"Interfaces gráficas de usuario","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/interfaces-graficas","x":"Informática II · 120 h · Contenido 5 de 8 Interfaces gráficas de usuario Una interfaz gráfica invierte el control: el programa ya no manda, espera. Ese cambio de mentalidad —del programa secuencial al bucle de eventos— es lo que hay que entender primero. Eventos Widgets Bucle de eventos Callbacks Diseño 01 El programa deja de mandar Un programa de consola manda: pide un dato, calcula, imprime, termina. Una interfaz gráfica invierte esa relación. El programa arranca, dibuja la ventana y se queda esperando; quien decide qué pasa es el usuario. Programa secuencial Programa orientado a eventos El código controla el orden El usuario controla el orden scanf bloquea hasta que haya dato Nadie…"},{"t":"Cálculo numérico aplicado","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/calculo-numerico","x":"Informática II · 120 h · Contenido 6 de 8 Cálculo numérico aplicado La computadora no calcula con números reales sino con aproximaciones, y esa diferencia tiene consecuencias. Los métodos numéricos resuelven lo que no tiene solución analítica, siempre con un error que hay que saber acotar. Punto flotante Bisección Newton Mínimos cuadrados Error 01 La computadora no calcula con números reales Un double guarda 64 bits: un signo, 11 de exponente y 52 de mantisa. Con eso representa unos 16 dígitos decimales significativos y nada más. Todo lo demás se redondea. El mismo formato de la norma IEEE 754 que se estudia en Informática I, ahora visto desde sus consecuencias. Tres consecuencias que…"},{"t":"Introducción a un lenguaje avanzado","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/lenguaje-avanzado","x":"Informática II · 120 h · Contenido 7 de 8 Introducción a un lenguaje avanzado Después de C, un lenguaje con objetos permite pensar en piezas que se arman entre sí. No es una moda: es la manera de que un proyecto de diez mil líneas siga siendo comprensible. Objetos Clases Encapsulamiento Excepciones Bibliotecas 01 Por qué no alcanza con funciones En C un programa crece como una lista de funciones que se pasan estructuras. Funciona hasta que el proyecto llega a unas miles de líneas y aparecen tres problemas: cualquiera puede tocar cualquier campo, el mismo dato se valida en veinte lugares, y agregar un caso obliga a buscar todos los if desperdigados. Las tres ideas que resuelven eso…"},{"t":"Fundamentos de sistemas operativos","d":"Tema · Informática II","u":"/publicaciones/mapa-ingenieria/temas/sistemas-operativos","x":"Informática II · 120 h · Contenido 8 de 8 Fundamentos de sistemas operativos El sistema operativo es el que reparte el procesador, la memoria y los periféricos entre programas que se creen dueños de la máquina. Entender cómo lo hace explica casi todos los comportamientos raros de un programa. Procesos Hilos Planificación Memoria virtual Tiempo real 01 El que reparte la máquina Un programa se escribe como si fuera dueño del procesador, de la memoria y de los periféricos. No lo es: hay decenas corriendo a la vez. El sistema operativo mantiene esa ilusión y reparte lo que hay. Recurso Lo que ve el programa Lo que hay de verdad Procesador Uno para él solo Unos pocos núcleos repartidos en…"},{"t":"El plano complejo y sus regiones","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/plano-complejo","x":"Análisis de Señales y Sistemas · 144 h · Contenido 1 de 34 El plano complejo y sus regiones Los complejos no son un artificio: son la herramienta natural para todo lo que oscila. Un fasor, una impedancia y un polo son puntos de este plano, y las regiones que se dibujan en él dicen si un circuito es estable. Plano complejo Forma polar Euler Regiones Fasores 01 Por qué un electrónico necesita los complejos La palabra «imaginario» es una desgracia histórica: sugiere que no existe. En electrónica, el plano complejo es el lugar donde viven las cosas más concretas de la carrera. Objeto del plano complejo Qué es en electrónica Un punto en forma polar Un fasor: amplitud y fase de una señal senoidal…"},{"t":"Funciones de variable compleja","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/funciones-complejas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 2 de 34 Funciones de variable compleja Una función compleja no se grafica con una curva: se muestra en qué convierte cada figura del plano. Así se entiende de dónde sale la carta de Smith, y por qué la exponencial compleja describe todo lo que oscila y se apaga. Mapeo Exponencial compleja Logaritmo Conforme Bilineal 01 Una función que no se puede graficar Una función real se dibuja con una curva: dos ejes alcanzan. Una función compleja toma un punto del plano y devuelve otro punto del plano: harían falta cuatro dimensiones para graficarla. La salida es dibujar dos planos, el de partida y el de llegada, y mostrar en qué se convierte cada…"},{"t":"Límite, continuidad y derivada compleja","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/limite-derivada-compleja","x":"Análisis de Señales y Sistemas · 144 h · Contenido 3 de 34 Límite, continuidad y derivada compleja La definición de derivada es la misma que en cálculo real, pero ahora el incremento puede llegar por infinitas direcciones y el cociente tiene que dar lo mismo en todas. Esa sola exigencia es la que hace que la variable compleja sea tan distinta. Límite Continuidad Derivada Analítica Cociente incremental 01 Un límite con infinitos caminos En una variable real, acercarse a un punto admite apenas dos caminos: por izquierda y por derecha. Por eso alcanza con los dos límites laterales. En el plano complejo, puede acercarse a por infinitas direcciones y, además, por curvas en espiral. El límite…"},{"t":"Ecuaciones de Cauchy-Riemann","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/cauchy-riemann","x":"Análisis de Señales y Sistemas · 144 h · Contenido 4 de 34 Ecuaciones de Cauchy-Riemann Dos ecuaciones en derivadas parciales amarran la parte real con la imaginaria: en una función derivable no se pueden elegir por separado. De ahí salen las funciones armónicas y, con ellas, el cálculo de campos. Cauchy-Riemann Parciales Armónicas Laplace Potencial complejo 01 Dos caminos, una condición En el contenido anterior quedó claro que la derivada compleja exige que el cociente incremental dé lo mismo por cualquier dirección. Basta con imponer que dos direcciones coincidan para obtener una condición sobre las partes real e imaginaria. Escribamos y acerquémonos primero por el eje real, con : Y ahora…"},{"t":"Funciones analíticas y mapeo conforme","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/mapeo-conforme","x":"Análisis de Señales y Sistemas · 144 h · Contenido 5 de 34 Funciones analíticas y mapeo conforme Cerca de un punto, toda función analítica se reduce a multiplicar por un número complejo: escalar y girar. Eso, y nada más, es lo que hace que los ángulos se conserven y que la carta de Smith se pueda dibujar con compás. Conforme Puntos críticos Carta de Smith Nyquist Schwarz-Christoffel 01 Analítica, y lo que eso arrastra Recapitulando: es analítica en un dominio si es derivable en sentido complejo en todos sus puntos, lo que por Cauchy-Riemann equivale a que y estén amarradas entre sí. Esa exigencia, que al principio parece técnica, trae consecuencias geométricas muy concretas, y de ahí sale…"},{"t":"Integrales de línea en el plano complejo","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/integrales-complejas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 6 de 34 Integrales de línea en el plano complejo Entre dos puntos del plano hay infinitos caminos, y la integral se define sobre uno de ellos. Cada término de la suma es un vector, así que la integral se puede ver: es una cadena de flechitas cuyo extremo es el resultado. Integral de contorno Parametrizar 2πj Cota ML Bromwich 01 Integrar a lo largo de un camino En una variable real, tiene un solo recorrido posible: del punto al punto sobre la recta. En el plano hay infinitos caminos entre dos puntos, y la integral se define sobre uno de ellos. La notación lo dice: La misma suma de Riemann de siempre, salvo que ahora cada término es un…"},{"t":"Teorema integral de Cauchy","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/teorema-cauchy","x":"Análisis de Señales y Sistemas · 144 h · Contenido 7 de 34 Teorema integral de Cauchy Si la función es analítica adentro, la integral sobre cualquier curva cerrada vale cero. De ahí sale lo que más se usa: un contorno se puede deformar a gusto mientras no cruce una singularidad. Cauchy-Goursat Green Deformar contornos Simplemente conexo Nyquist 01 El enunciado Es el resultado que ordena toda la segunda mitad de la variable compleja, y se dice en un renglón. Para toda curva cerrada contenida en . No hay que calcular nada: si la función es analítica adentro, la integral es cero. Dos palabras del enunciado hacen todo el trabajo. Analítica, que ya se sabe qué significa. Y simplemente conexo: un…"},{"t":"Fórmula integral de Cauchy","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/formula-cauchy","x":"Análisis de Señales y Sistemas · 144 h · Contenido 8 de 34 Fórmula integral de Cauchy Los valores de una función analítica sobre una curva cerrada determinan por completo lo que vale en todo el interior. No hay nada parecido en el cálculo real, y de esa rigidez salen Liouville y el teorema fundamental del álgebra. Fórmula de Cauchy Valor medio Derivadas Liouville Módulo máximo 01 El valor adentro, leído desde el borde El teorema anterior dice cuándo una integral vale cero. Éste hace algo mucho más fuerte: dice que los valores de una función analítica sobre una curva cerrada determinan por completo lo que la función vale en todo el interior. Con analítica dentro y sobre , y un punto interior…"},{"t":"Polos y ceros","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/polos-y-ceros","x":"Análisis de Señales y Sistemas · 144 h · Contenido 9 de 34 Polos y ceros Una constante y un puñado de puntos del plano contienen todo el circuito: la respuesta en frecuencia, la respuesta al escalón y la estabilidad salen de leer dónde están esos puntos. Polos Ceros Estabilidad Q Bode 01 Los dos números que definen un circuito Una función de transferencia de parámetros concentrados es siempre un cociente de polinomios, y todo polinomio se factorea. Entonces: Los son los ceros: ahí vale cero. Los son los polos: ahí se va a infinito. Esa factorización dice algo fuerte: una constante y un puñado de puntos del plano contienen toda la información del circuito. La respuesta en frecuencia, la…"},{"t":"Singularidades","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/singularidades","x":"Análisis de Señales y Sistemas · 144 h · Contenido 10 de 34 Singularidades Hay exactamente tres maneras de que una función no esté definida en un punto aislado, y la serie de Laurent las distingue de un vistazo. La tercera, la esencial, es la que hace que un retardo puro no se deje escribir con polos y ceros. Laurent Evitable Polo de orden m Esencial Ramificación 01 Tres maneras de no estar definida Un punto es una singularidad aislada de si la función es analítica en un entorno de salvo en mismo. La clasificación se hace mirando qué pasa al acercarse, y hay exactamente tres casos posibles. Tipo Qué hace al acercarse Ejemplo Evitable Tiende a un valor finito en Polo de orden Tiende a…"},{"t":"Teorema de los residuos","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/residuos","x":"Análisis de Señales y Sistemas · 144 h · Contenido 11 de 34 Teorema de los residuos Una integral sobre una curva entera queda reducida a sumar unos pocos números, uno por singularidad. Y esos números ya los conocían: son los coeficientes de la descomposición en fracciones simples. Residuos Laurent Fracciones simples Antitransformada Bromwich 01 Todo se reduce a un coeficiente Al integrar la serie de Laurent término a término sobre un contorno cerrado, todos los términos dan cero salvo uno: el de , que da . Ese coeficiente, el del desarrollo, es el residuo, y es lo único de la función que sobrevive a la integral. La suma recorre las singularidades encerradas por , recorrido una vez en…"},{"t":"Residuos aplicados a integrales reales","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/residuos-aplicaciones","x":"Análisis de Señales y Sistemas · 144 h · Contenido 12 de 34 Residuos aplicados a integrales reales Hay integrales reales sin primitiva elemental que salen en dos renglones si se las saca del eje real y se las cierra en el plano complejo. De ahí sale el ancho de banda de ruido de un filtro, entre otras cosas. Residuos Lema de Jordan Valor principal Ancho de banda de ruido Fourier 01 Una integral real, resuelta por afuera Hay integrales reales que no tienen primitiva elemental y que, sin embargo, salen en dos renglones si se las saca del eje real y se las cierra en el plano complejo. La maniobra es siempre la misma: Se reemplaza la variable real por una compleja y se agrega un arco que cierre…"},{"t":"Señales de tiempo continuo y discreto","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/senales-continuas-discretas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 13 de 34 Señales de tiempo continuo y discreto Lo único que cambia entre los dos mundos de la materia es dónde vive la variable independiente. Pero esa diferencia trae consecuencias: en tiempo discreto no toda senoidal es periódica, y la frecuencia queda encerrada en un intervalo. Tiempo discreto Digital Periodicidad Energía Potencia 01 Dos variables independientes, dos mundos Una señal es una función que lleva información. Lo único que cambia entre los dos mundos de esta materia es el conjunto donde vive la variable independiente: Paréntesis y para tiempo continuo; corchetes y para tiempo discreto. La notación no es decorativa: avisa de…"},{"t":"Transformaciones de la variable independiente","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/transformaciones-variable","x":"Análisis de Señales y Sistemas · 144 h · Contenido 14 de 34 Transformaciones de la variable independiente Tres operaciones y nada más: correr, espejar y estirar. El problema aparece cuando se combinan, porque el desplazamiento de x(at+b) no es b sino b/a, y ahí se equivoca todo el mundo alguna vez. Desplazamiento Reflexión Escalamiento Puntos notables Diezmado 01 Tres operaciones y nada más Todo lo que se le puede hacer al eje del tiempo de una señal se arma con tres movimientos: Operación Expresión Qué hace Desplazamiento Con corre hacia la derecha: es un retardo Reflexión Espeja respecto del eje vertical: el futuro pasa a ser pasado Escalamiento Con comprime; con , expande Las dos…"},{"t":"Señales pares e impares","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/pares-impares","x":"Análisis de Señales y Sistemas · 144 h · Contenido 15 de 34 Señales pares e impares Toda señal se parte en una par y una impar, de una sola manera. Esa partición decide qué armónicos puede tener y explica por qué una etapa push-pull cancela los pares. Par e impar Descomposición Simetría hermítica Armónicos Push-pull 01 Dos simetrías Una señal es par si espejarla en el tiempo no la cambia, e impar si espejarla equivale a cambiarle el signo: En tiempo discreto es lo mismo, con en lugar de . El coseno es par, el seno es impar, y una señal cualquiera no es ni una cosa ni la otra. De ahí sale una observación menor: toda señal impar vale cero en el origen, porque obliga a . Lo interesante no es…"},{"t":"La señal exponencial compleja","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/exponencial-compleja","x":"Análisis de Señales y Sistemas · 144 h · Contenido 16 de 34 La señal exponencial compleja Si entra una exponencial compleja a un sistema LTI, sale la misma exponencial multiplicada por un número. Ninguna otra señal hace eso, y de ahí sale todo el análisis en frecuencia. Autofunción Euler Plano s Fasores Frecuencia negativa 01 La función más importante de la materia Hay una razón precisa por la que todo el análisis de señales gira alrededor de la exponencial compleja, y no es estética. Es esta: La forma de onda sale igual que entró. Lo único que cambia es un factor complejo, , que depende del sistema y del valor de . Ninguna otra familia de señales tiene esa propiedad. Si entra un pulso,…"},{"t":"Sistemas lineales e invariantes en el tiempo","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/sistemas-lti","x":"Análisis de Señales y Sistemas · 144 h · Contenido 17 de 34 Sistemas lineales e invariantes en el tiempo Dos propiedades, y con ellas basta una sola medición para conocer el sistema entero. También explican por qué para trasladar una señal en frecuencia hay que romper alguna de las dos. Linealidad Invarianza LTI Respuesta al impulso Mezclador 01 Linealidad: superposición Un sistema es una caja que recibe una señal y devuelve otra. Es lineal si responde a una combinación de entradas con la misma combinación de sus salidas: Con y constantes cualesquiera, incluso complejas. Esta única condición contiene la aditividad y la homogeneidad. De ahí se desprende algo que sorprende siempre: tomando ,…"},{"t":"Causalidad","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/causalidad","x":"Análisis de Señales y Sistemas · 144 h · Contenido 18 de 34 Causalidad La salida de hoy no puede depender de la entrada de mañana. Esa única exigencia es la que hace que ningún filtro real tenga un corte vertical, y la que explica la latencia de cualquier procesamiento digital de audio. Causalidad Memoria Fase lineal Paley-Wiener Latencia 01 No adivinar el futuro Un sistema es causal si su salida en un instante depende solamente de lo que pasó hasta ese instante, nunca de lo que va a pasar después: También se los llama no anticipativos. Todo sistema que funcione en tiempo real tiene que serlo, porque el futuro todavía no llegó. Para un sistema LTI la condición se traduce en una sola frase…"},{"t":"Estabilidad","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/estabilidad","x":"Análisis de Señales y Sistemas · 144 h · Contenido 19 de 34 Estabilidad Toda entrada acotada tiene que dar una salida acotada, y alcanza con una sola excepción para descartar la estabilidad. Un integrador ideal es el ejemplo más cercano: no la cumple. BIBO Integrabilidad Peor caso Polos Integrador 01 Entrada acotada, salida acotada El criterio de estabilidad que se usa en señales tiene nombre propio: BIBO, por bounded input, bounded output. Un sistema es estable si toda entrada acotada produce una salida acotada: La palabra clave es toda. Basta con encontrar una sola entrada acotada que haga crecer la salida para que el sistema sea inestable. Eso último es lo que hace que la verificación…"},{"t":"Impulso y escalón unitarios","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/impulso-escalon","x":"Análisis de Señales y Sistemas · 144 h · Contenido 20 de 34 Impulso y escalón unitarios El impulso no es una función con forma: es el límite de cualquier familia de pulsos que se angoste manteniendo área uno. Lo único que hay que saber de él es cómo se comporta adentro de una integral. Escalón Impulso Cribado Distribución Respuesta al impulso 01 El escalón, que no tiene misterio Empecemos por el fácil. El escalón unitario vale cero antes y uno después: En tiempo continuo el valor en se deja sin definir, o se lo toma por conveniencia. En discreto no hay ambigüedad: . Su utilidad principal es recortar. Multiplicar por apaga todo lo anterior a cero, y restando dos escalones corridos se arma un…"},{"t":"Convolución","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/convolucion","x":"Análisis de Señales y Sistemas · 144 h · Contenido 21 de 34 Convolución Reflejar, correr, multiplicar y medir el área. Con esos cuatro pasos, y conociendo la respuesta al impulso, se calcula la salida de un sistema LTI para cualquier entrada. Convolución Respuesta al impulso Cascada Duración Convolución discreta 01 Por qué la integral es así La convolución no es una definición caída del cielo: sale de aplicar linealidad e invarianza a la descomposición de una señal en impulsos. El razonamiento ya se esbozó al hablar de sistemas LTI y conviene tenerlo completo: Cada instante de la entrada dispara una copia de , escalada por el valor que tenía la entrada en ese instante y corrida hasta ahí.…"},{"t":"Señales periódicas","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/senales-periodicas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 22 de 34 Señales periódicas De una señal periódica interesan cuatro números, y de dos de ellos sale el factor de forma: el 1,111 que un multímetro barato aplica a ciegas, y que lo hace equivocarse con cualquier onda que no sea senoidal. Período Valor eficaz Factor de forma Factor de cresta Multímetro 01 Repetirse exactamente Una señal es periódica si existe un positivo que la devuelve a sí misma: El menor que lo cumple es el período fundamental. En tiempo discreto, tiene que ser entero, con las consecuencias que ya se vieron. Si sirve, también sirven , y todos sus múltiplos. Por eso se habla del fundamental: es el que define la frecuencia…"},{"t":"Series e integrales de Fourier","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/series-fourier","x":"Análisis de Señales y Sistemas · 144 h · Contenido 23 de 34 Series e integrales de Fourier Toda señal periódica razonable es una suma de senoidales cuyas frecuencias son múltiplos de la fundamental. Y como cada una atraviesa un sistema LTI sin cambiar de forma, alcanza con saber qué le pasa a cada armónica. Serie de Fourier Ortogonalidad Dirichlet Gibbs Espectro 01 Armar cualquier periódica con senoidales El resultado que abre la segunda mitad de la materia es éste: toda señal periódica razonable se puede escribir como una suma de exponenciales complejas armónicamente relacionadas, es decir, de senoidales cuyas frecuencias son múltiplos enteros de la fundamental. La forma exponencial. Es la…"},{"t":"Propiedades de la transformada","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/propiedades-fourier","x":"Análisis de Señales y Sistemas · 144 h · Contenido 24 de 34 Propiedades de la transformada Cada propiedad dice qué le pasa al espectro cuando se toca la señal. Con ellas se resuelven problemas sin volver a integrar nunca, y sale la regla del tiempo de subida que se usa todos los días en el laboratorio. Propiedades Desplazamiento Escalamiento Modulación Dualidad 01 La tabla que hay que saber leer Las propiedades de la transformada no son curiosidades para memorizar: cada una dice qué le pasa al espectro cuando se toca la señal, y al revés. Son las que permiten resolver problemas sin volver a integrar nunca. En el tiempo En la frecuencia Qué significa Linealidad: todo se puede descomponer El…"},{"t":"Espectros","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/espectros","x":"Análisis de Señales y Sistemas · 144 h · Contenido 25 de 34 Espectros Un analizador no puede observar para siempre, y ese recorte tiene consecuencias: un tono puro aparece desparramado. Las ventanas lo corrigen a costa de resolución, y elegir una es elegir qué se pierde. Espectro Densidad espectral Fuga Ventanas Resolución 01 Qué se grafica cuando se grafica un espectro La transformada devuelve un número complejo por cada frecuencia, así que hacen falta dos gráficos para mostrarla entera: el de amplitud y el de fase. En la práctica casi siempre se mira el de amplitud, y por una razón: el oído y la mayoría de los detectores son insensibles a la fase. Pero la fase está, y es la que guarda la…"},{"t":"Relación de Parseval","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/parseval","x":"Análisis de Señales y Sistemas · 144 h · Contenido 26 de 34 Relación de Parseval La energía de una señal es la misma calculada en el tiempo o en la frecuencia. De esa igualdad salen la distorsión armónica, el cálculo de ruido y la idea que hace posible el JPEG y el MP3. Parseval Potencia THD Ruido Compresión 01 La energía no depende de dónde se la mire Una señal tiene una cierta energía. Esa energía se puede calcular sumando su cuadrado a lo largo del tiempo, o sumando el cuadrado de su espectro a lo largo de la frecuencia, y el resultado es el mismo. Eso es la relación de Parseval: Para señales aisladas, de energía finita. El desaparece si se trabaja en hertz en lugar de radianes por…"},{"t":"Respuesta en frecuencia","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/respuesta-frecuencia","x":"Análisis de Señales y Sistemas · 144 h · Contenido 27 de 34 Respuesta en frecuencia Un sistema LTI no mezcla frecuencias: cada armónico sale escalado y desfasado, sin enterarse de los demás. Pero mirar sólo el módulo no alcanza, y un pasatodo lo demuestra. Bode Asíntotas Retardo de grupo Fase mínima Margen de fase 01 Lo que el sistema le hace a cada frecuencia Si una exponencial compleja entra a un sistema LTI y sale multiplicada por , entonces evaluando sobre el eje imaginario se obtiene lo que le pasa a cada frecuencia real: El espectro de la salida es el de la entrada, multiplicado frecuencia por frecuencia. La convolución del tiempo se volvió un producto. Eso significa que un sistema…"},{"t":"Representación de señales y sistemas","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/representacion-sistemas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 28 de 34 Representación de señales y sistemas Cuatro maneras de describir lo mismo, y ninguna más verdadera que las otras. Cada problema se resuelve fácil desde una de ellas, y buena parte del oficio consiste en elegir desde dónde mirar. Ecuación diferencial Función de transferencia Variables de estado Ecuación en diferencias Plano z 01 El mismo sistema, cuatro descripciones Un sistema LTI se puede describir de cuatro maneras distintas, y las cuatro dicen exactamente lo mismo. No son alternativas entre las que haya que elegir: son puntos de vista, y cada problema se resuelve más fácil desde uno de ellos. Representación Forma Buena para…"},{"t":"Elementos de los sistemas e implementación","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/implementacion-sistemas","x":"Análisis de Señales y Sistemas · 144 h · Contenido 29 de 34 Elementos de los sistemas e implementación Sumador, ganancia y memoria: con esas tres piezas se arma cualquier sistema. Cómo se las acomoda no es indiferente, y de ahí sale que ningún filtro digital de orden alto se implemente en forma directa. Diagrama de bloques Forma directa Biquad FIR IIR 01 Tres piezas y nada más Cualquier sistema LTI, por complicado que sea, se arma con tres elementos. No hay un cuarto: Elemento Qué hace En continuo En discreto Sumador Un nodo, o un amplificador sumador Una suma Ganancia Un divisor resistivo, una etapa Una multiplicación Memoria Guarda el pasado Un integrador: capacitor o bobina Un retardo :…"},{"t":"Teorema del muestreo","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/muestreo-shannon","x":"Análisis de Señales y Sistemas · 144 h · Contenido 30 de 34 Teorema del muestreo Quedarse con el valor cada T segundos y tirar el resto parece perder información para siempre. Y sin embargo, si la señal tiene banda limitada y se muestrea rápido, las muestras contienen todo. Nyquist Réplicas Interpolación sinc Retenedor Filtro antialias 01 El enunciado, y por qué no es obvio Muestrear es quedarse con el valor de una señal cada segundos y tirar todo lo que pasaba en el medio. Parece que se pierde información para siempre, y sin embargo: Si la señal tiene ancho de banda limitado y se muestrea a más del doble de su frecuencia más alta, las muestras contienen toda la información. Nada se perdió.…"},{"t":"Aliasing","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/aliasing","x":"Análisis de Señales y Sistemas · 144 h · Contenido 31 de 34 Aliasing Una frecuencia alta que se disfraza de una baja. El problema no es que se distorsione: es que después no hay manera de darse cuenta, porque las muestras son exactamente las mismas. Aliasing Plegado Antialias Sobremuestreo Sigma-delta 01 Una frecuencia que se disfraza de otra Cuando la frecuencia de muestreo no alcanza, las réplicas del espectro se meten en la banda útil y una señal alta aparece en el lugar de una baja. Se la llama alias, y la frecuencia con la que se presenta sale de una cuenta simple: La frecuencia se «pliega» dentro de la banda, como si el eje se doblara en y en cada múltiplo de . El problema no es que…"},{"t":"Teoremas de convolución y modulación","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/convolucion-modulacion","x":"Análisis de Señales y Sistemas · 144 h · Contenido 32 de 34 Teoremas de convolución y modulación Convolucionar en un dominio es multiplicar en el otro. El primer teorema permite analizar filtros; el segundo permite mover señales en frecuencia, y de él sale toda la radio. Convolución Modulación Bandas laterales AM Eficiencia 01 Dos teoremas que son el mismo Ya aparecieron sueltos; conviene verlos juntos porque su simetría es la que organiza medio procesamiento de señales: Convolucionar en un dominio es multiplicar en el otro. La única asimetría es el , que desaparece trabajando en hertz. El primero es el que permite analizar filtros. El segundo es el que permite mover señales en frecuencia,…"},{"t":"Transformada de Laplace","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/laplace","x":"Análisis de Señales y Sistemas · 144 h · Contenido 33 de 34 Transformada de Laplace Fourier deja afuera todo lo que crece. Laplace agrega un factor de convergencia y con él entran el escalón, los sistemas inestables y las condiciones iniciales. El precio es que hay que decir siempre dónde converge. Laplace Región de convergencia Unilateral Impedancias Valor final 01 Para qué, si ya está Fourier La transformada de Fourier necesita que la señal sea absolutamente integrable, y eso deja afuera a cosas tan comunes como el escalón o una exponencial creciente. La solución de Laplace es multiplicar por un factor de convergencia antes de transformar: Con queda exactamente la transformada de Fourier.…"},{"t":"Transformada Z y nociones de filtrado","d":"Tema · Análisis de Señales y Sistemas","u":"/publicaciones/mapa-ingenieria/temas/transformada-z","x":"Análisis de Señales y Sistemas · 144 h · Contenido 34 de 34 Transformada Z y nociones de filtrado Lo mismo que Laplace, para secuencias. El eje imaginario se vuelve el círculo unitario, y todo lo que se sabía de estabilidad se traduce cambiando «izquierda del eje» por «adentro del círculo». Transformada Z Círculo unitario Polos y ceros Notch Filtros digitales 01 Laplace, para secuencias La transformada Z es a las señales discretas lo que Laplace a las continuas. La definición reemplaza la integral por una suma y la exponencial por una potencia: Cada muestra se multiplica por . Como es el retardo de una muestra, la transformada es la ecuación en diferencias escrita de otra manera. Y la…"},{"t":"Sistemas materiales","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/sistemas-materiales","x":"Química General · 120 h · Contenido 1 de 12 Sistemas materiales Un transistor exige un silicio con menos de un átomo extraño cada mil millones. Llegar a esa pureza es un problema de separación de mezclas, y se resuelve con una técnica que se entiende con lo que se ve en esta unidad. Sustancia pura Mezclas Fases Separación Refinado de zona 01 Cómo se clasifica lo que hay Todo lo que se puede tocar es un sistema material, y la primera pregunta es si tiene una sola composición o varias. De ahí sale la clasificación entera: Sistema Fases Se separa Ejemplo del taller Sustancia pura simple Una No se separa Cobre de un cable, estaño Sustancia pura compuesta Una Sólo por reacción química Óxido de…"},{"t":"Notación y cantidad de sustancia","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/cantidad-sustancia","x":"Química General · 120 h · Contenido 2 de 12 Notación y cantidad de sustancia Contar átomos parece imposible y se hace todos los días: un dopaje de 10¹⁶ átomos por centímetro cúbico es dos partes por millón, y de ese número depende la resistividad de una oblea. Mol Avogadro Masa molar Dopaje Partes por millón 01 El mol: una docena muy grande Los átomos son tan chicos que contarlos de a uno no sirve. La química usa un paquete de tamaño fijo, igual que se usa la docena para los huevos, sólo que muchísimo más grande: Desde 2019 ese número es una definición exacta, igual que la velocidad de la luz: el mol se define como esa cantidad, y no al revés. La gracia del número es que fue elegido para…"},{"t":"Estructura de la materia","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/estructura-materia","x":"Química General · 120 h · Contenido 3 de 12 Estructura de la materia Que el silicio tenga cuatro electrones de valencia y el fósforo cinco no es un dato suelto: es la razón de que uno forme cristales y el otro sirva para doparlos. Toda la electrónica del estado sólido empieza acá. Orbitales Números cuánticos Configuración Tabla periódica Valencia 01 Dónde están los electrones El modelo de Bohr —electrones girando en órbitas— alcanza para dibujar, pero no para explicar. El modelo actual dice que un electrón no tiene una trayectoria sino una distribución de probabilidad, y que su estado queda descripto por cuatro números: Número Qué dice Valores , principal El nivel de energía, el «tamaño» 1,…"},{"t":"Uniones químicas","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/uniones-quimicas","x":"Química General · 120 h · Contenido 4 de 12 Uniones químicas Que un material conduzca, aísle o esté en el medio no depende de sus átomos sino de cómo se unen. De ahí salen las bandas de energía, y de las bandas, todo dispositivo de estado sólido. Electronegatividad Iónico y covalente Bandas Banda prohibida Niveles de impureza 01 Tres maneras de compartir electrones Los átomos se unen porque así bajan su energía, y lo hacen de tres maneras según cuánto se disputen los electrones. Quien decide es la electronegatividad: la tendencia de cada átomo a atraer hacia sí los electrones del enlace. Enlace Diferencia Qué pasa Ejemplo Iónico Uno se los arranca al otro: quedan iones NaCl, óxidos…"},{"t":"Estados de agregación de la materia","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/estados-agregacion","x":"Química General · 120 h · Contenido 5 de 12 Estados de agregación de la materia Los chips se fabrican en cámaras de vacío, y la razón no es la limpieza: es que a 10⁻⁶ torr un átomo evaporado recorre cincuenta metros sin chocar con nada. Gases ideales Van der Waals Diagrama de fases Punto triple Vacío 01 Los gases, y por qué son los fáciles En un gas las moléculas están tan separadas que casi no se ven entre sí. Esa indiferencia mutua es lo que permite describirlo con una sola ecuación, la misma para todos los gases: Un mol de cualquier gas ocupa 22,4 litros a 0 °C y 1 atm. No importa cuál sea el gas: eso es lo notable. La ecuación falla cuando el gas se comprime o se enfría lo suficiente…"},{"t":"Estequiometría y energía de las reacciones","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/estequiometria","x":"Química General · 120 h · Contenido 6 de 12 Estequiometría y energía de las reacciones Al oxidar un micrón de silicio crecen 2,27 micrones de óxido. Ese número no sale de una medición: sale de la ecuación balanceada, y hay que tenerlo en cuenta al diseñar el espesor de compuerta. Balanceo Reactivo limitante Rendimiento Entalpía Ley de Hess 01 La ecuación balanceada es una receta Una ecuación química balanceada no dice qué pasa: dice en qué proporción pasa. Los coeficientes son la receta, y se leen en moles, no en gramos ni en volúmenes. Un mol de silicio con un mol de oxígeno da un mol de dióxido. En masa: 28,09 g de silicio con 31,99 g de oxígeno dan 60,08 g de óxido, porque la masa se…"},{"t":"Soluciones","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/soluciones","x":"Química General · 120 h · Contenido 7 de 12 Soluciones El agua más pura que se fabrica mide 18,2 MΩ·cm, y ese número no es una meta de purificación sino un límite físico: el agua se ioniza a sí misma y esos iones propios ponen el piso. Concentración Solubilidad Electrolitos Kohlrausch Coligativas 01 Cuánto hay de qué Una solución es una mezcla homogénea: el soluto queda disperso en el solvente a escala molecular, sin superficie de separación. Lo único que hay que decidir es cómo se informa cuánto hay, y ahí conviven media docena de unidades que no son intercambiables. Unidad Definición Cuándo conviene Molaridad Moles de soluto por litro de solución Para reaccionar: es la que entra en los…"},{"t":"Cinética química","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/cinetica","x":"Química General · 120 h · Contenido 8 de 12 Cinética química Que la vida de un capacitor electrolítico se reduzca a la mitad cada 10 °C no es una regla empírica suelta: es la ecuación de Arrhenius con una energía de activación de 0,83 electronvoltios. Velocidad Orden de reacción Arrhenius Energía de activación Vida útil 01 Qué tan rápido, no si ocurre La termodinámica dice si una reacción puede ocurrir; la cinética, cuánto tarda. Son preguntas independientes, y confundirlas lleva a conclusiones absurdas. La oxidación del silicio al aire es espontánea y muy exotérmica, y sin embargo una oblea no se deshace: la capa nativa crece dos nanómetros y se detiene, porque a temperatura ambiente la…"},{"t":"Equilibrio químico","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/equilibrio","x":"Química General · 120 h · Contenido 9 de 12 Equilibrio químico Le Chatelier dice que el amoníaco conviene hacerlo frío, y la cinética dice que frío no se hace nunca. Casi todo proceso industrial vive en la negociación entre esas dos respuestas. Reversibilidad Constante K Le Chatelier Van 't Hoff Haber-Bosch 01 Las reacciones que vuelven Muchas reacciones no terminan: llegan a un punto en el que la ida y la vuelta ocurren a la misma velocidad y las concentraciones dejan de cambiar. Eso es el equilibrio químico, y es dinámico: abajo sigue pasando todo, pero el balance neto es cero. La constante de equilibrio depende solo de la temperatura. No la cambia la presión, ni las cantidades iniciales,…"},{"t":"Equilibrio en soluciones","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/equilibrio-soluciones","x":"Química General · 120 h · Contenido 10 de 12 Equilibrio en soluciones El fluorhídrico es un ácido débil y es el reactivo más peligroso de un laboratorio de electrónica. Esas dos cosas no se contradicen: la fuerza de un ácido mide su equilibrio de disociación, no su toxicidad. pH Ka y pKa Titulación Reguladoras Producto de solubilidad 01 El agua se ioniza a sí misma Dos moléculas de agua intercambian un protón, y de ese equilibrio sale todo el resto. Su constante es chica pero no nula, y eso alcanza para fijar la escala en la que se mide la acidez: A 25 °C. De ahí sale que en agua pura y el pH vale 7, y que en cualquier solución acuosa. Y de ahí sale también el límite de resistividad del…"},{"t":"Electroquímica","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/electroquimica","x":"Química General · 120 h · Contenido 11 de 12 Electroquímica Que no se empalme cable de aluminio con cobre no es una manía de electricista: son dos voltios de diferencia en la tabla de potenciales, y con humedad eso es una pila que se come el aluminio. Redox Ánodo y cátodo Nernst Corrosión galvánica Baterías 01 Electrones que cambian de dueño Toda la electroquímica es una reacción de oxidación-reducción a la que se le obliga a pasar los electrones por un cable en lugar de entregarlos directamente. Esa es la única diferencia entre un clavo que se oxida y una batería: el camino. Ocurre en Qué pasa Electrodo Signo en una pila Oxidación La especie pierde electrones Ánodo Negativo Reducción La…"},{"t":"Química del ambiente","d":"Tema · Química General","u":"/publicaciones/mapa-ingenieria/temas/quimica-ambiente","x":"Química General · 120 h · Contenido 12 de 12 Química del ambiente Un kilogramo de hexafluoruro de azufre escapado de una cámara de grabado calienta lo mismo que veintitrés toneladas y media de dióxido de carbono. Es inerte, no es tóxico y no toca la capa de ozono: el problema es que no se va nunca. Ozono Efecto invernadero GWP RoHS y RAEE Efluentes 01 La atmósfera como reactor La química ambiental estudia reacciones que ocurren en sistemas que nadie diseñó y de los que nadie puede salirse. Dos de ellas se confunden todo el tiempo y conviene separarlas de entrada, porque tienen causas distintas, altura distinta y solución distinta. Agujero de ozono Efecto invernadero Dónde Estratosfera, 15 a…"},{"t":"Calor y temperatura","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/calor-temperatura","x":"Física II · 120 h · Contenido 1 de 15 Calor y temperatura Medir temperatura es convertirla en algo eléctrico, y hay cuatro maneras de hacerlo. Ninguna es la mejor: cada una gana en un rango y pierde en otro, y elegir mal el sensor arruina la medición antes de empezar. Temperatura Calor específico Dilatación Termocupla Pt100 y NTC 01 Temperatura no es calor Son dos cosas distintas y se confunden todo el tiempo. La temperatura mide la energía cinética media de las partículas: es una propiedad del estado. El calor es energía en tránsito entre dos cuerpos a distinta temperatura: existe mientras fluye y después deja de existir. Un cuerpo no «tiene» calor, igual que un capacitor no tiene…"},{"t":"Mecanismos de intercambio de calor","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/intercambio-calor","x":"Física II · 120 h · Contenido 2 de 15 Mecanismos de intercambio de calor La cadena térmica de un transistor se resuelve exactamente igual que un divisor resistivo: la potencia hace de corriente, la temperatura de tensión y cada interfaz de resistencia. Con esa analogía, calcular un disipador es un ejercicio de circuitos. Conducción Convección Radiación Resistencia térmica Disipadores 01 Tres maneras de mover calor El calor va siempre del cuerpo caliente al frío, y llega por tres caminos que actúan a la vez. En electrónica los tres están presentes en cualquier equipo, pero no pesan lo mismo. Mecanismo Cómo viaja Ley Dónde manda Conducción Por contacto, sin que la materia se mueva Del chip a…"},{"t":"Primer y Segundo Principio","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/principios-termodinamica","x":"Física II · 120 h · Contenido 3 de 15 Primer y Segundo Principio Borrar un bit tiene un costo energético mínimo que no depende de la tecnología: son kT·ln2 joules, y sale del Segundo Principio. La termodinámica le pone piso al consumo de una computadora. Primer Principio Entropía Carnot Peltier Landauer 01 El Primer Principio: la energía se conserva La energía interna de un sistema cambia por dos vías, y solamente dos: el calor que entra y el trabajo que se hace. Escrito así parece poco, y es el principio de conservación más general que existe. Con el criterio habitual: positivo cuando entra calor al sistema, positivo cuando el sistema hace trabajo sobre el entorno. En un ciclo completo el…"},{"t":"Electrostática","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/electrostatica","x":"Física II · 120 h · Contenido 4 de 15 Electrostática El umbral de daño de un MOSFET arranca en unos 100 V y el de percepción humana está cerca de los 3000. Un componente puede quedar destruido por una descarga que la persona no sintió. Ley de Coulomb Campo eléctrico Ley de Gauss Potencial Descarga electrostática 01 La ley de Coulomb y el campo Dos cargas en reposo se atraen o se repelen con una fuerza que cae con el cuadrado de la distancia. La forma es idéntica a la de la gravitación, con una diferencia decisiva: la carga tiene dos signos, y por eso la fuerza eléctrica puede cancelarse. Con F/m. Esa cancelación es lo que hace que la materia sea eléctricamente neutra a escala normal, y que…"},{"t":"Capacidad y capacitores","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/capacitores","x":"Física II · 120 h · Contenido 5 de 15 Capacidad y capacitores Un cerámico X7R de 10 µF puede quedar en menos de 3 µF cuando se le aplican 10 V, y eso no figura en la tolerancia impresa. Es la causa de fuentes que oscilan y de filtros que no filtran. Capacidad Dieléctricos Rigidez dieléctrica ESR Transitorio RC 01 Qué es la capacidad Dos conductores separados por un aislante guardan carga cuando se les aplica una diferencia de potencial. La capacidad mide cuánta carga guardan por cada volt, y depende solamente de la geometría y del material que hay en el medio: no de la tensión ni de la carga. Un farad es enorme: un capacitor plano de 1 F con aire y 1 mm de separación necesitaría placas de…"},{"t":"Propiedades eléctricas de la materia","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/propiedades-electricas","x":"Física II · 120 h · Contenido 6 de 15 Propiedades eléctricas de la materia El silicio puro y el silicio dopado son la misma sustancia y su resistividad difiere en un factor de casi un millón. Lo único que cambió fue un átomo de fósforo cada diez millones de átomos. Resistividad Coeficiente de temperatura Constantán Polarización Superconductividad 01 Veinticuatro órdenes de magnitud Ninguna otra propiedad física recorre un rango tan grande. Entre la plata y el cuarzo hay un factor de , y en el medio está el silicio, que puede colocarse casi donde uno quiera. La última es la ley de Ohm en forma local, que es la que vale de verdad: la versión sale de integrarla sobre un conductor de sección…"},{"t":"Circuitos de corriente continua","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/corriente-continua","x":"Física II · 120 h · Contenido 7 de 15 Circuitos de corriente continua La carga que entrega la máxima potencia es la que iguala a la resistencia interna, y justo ahí el rendimiento es del 50 %. Por eso en radiofrecuencia se adapta y en un sistema de energía jamás. Ley de Ohm Kirchhoff Divisores Thévenin Máxima transferencia 01 Corriente y ley de Ohm La corriente es carga que atraviesa una sección por unidad de tiempo. Su sentido convencional es el de las cargas positivas, aunque en un metal lo que se mueve son electrones y van al revés: es una convención heredada que conviene aceptar y no pelear. La ley de Ohm no es una ley universal: es una propiedad de ciertos materiales. Un diodo, una…"},{"t":"Magnetostática","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/magnetostatica","x":"Física II · 120 h · Contenido 8 de 15 Magnetostática No hay cargas magnéticas, así que el campo magnético no se define por la fuerza sobre una carga quieta —esa es cero— sino sobre una en movimiento. De ahí sale todo, desde el motor hasta el sensor de Hall. Fuerza de Lorentz Biot-Savart Ley de Ampère Solenoide Efecto Hall 01 El campo magnético se define por lo que hace No hay cargas magnéticas: no existe el equivalente magnético de un electrón. Por eso el campo magnético no se define por la fuerza sobre una carga en reposo —esa es cero— sino por la fuerza sobre una carga en movimiento, y esa fuerza es perpendicular a todo. Fuerza de Lorentz, y su versión para un conductor. Al ser…"},{"t":"Inducción magnética","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/induccion-magnetica","x":"Física II · 120 h · Contenido 9 de 15 Inducción magnética Cortar un ampere en un microsegundo sobre una bobina de 10 mH genera diez mil volts. La bobina produce la tensión que haga falta con tal de que su corriente no cambie de golpe, y si nadie le da un camino, se lo abre ella. Faraday Lenz Autoinducción Transformador Foucault 01 La ley de Faraday Un campo magnético que cambia en el tiempo crea un campo eléctrico. Ese es el descubrimiento que separa la electricidad del magnetismo como temas distintos y los une en uno solo, y es el que hace posible generar energía eléctrica a escala. Tercera ecuación de Maxwell. Lo que induce fem no es el campo sino su variación: una espira quieta en un…"},{"t":"Propiedades magnéticas de la materia","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/propiedades-magneticas","x":"Física II · 120 h · Contenido 10 de 15 Propiedades magnéticas de la materia El área del ciclo de histéresis es energía perdida en cada vuelta. Multiplicada por la frecuencia da los watts que calientan el núcleo, y de ese número sale la elección del material de todo transformador. Permeabilidad Dominios Histéresis Saturación Curie 01 Tres respuestas al campo Todo material responde a un campo magnético, aunque en casi todos la respuesta sea imperceptible. La magnitud que la mide es la permeabilidad relativa, y según su valor los materiales se parten en tres grupos muy desparejos. es la excitación, la que producen las corrientes que uno controla; es la inducción resultante, que incluye lo que…"},{"t":"Ecuaciones de Maxwell","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/maxwell","x":"Física II · 120 h · Contenido 11 de 15 Ecuaciones de Maxwell Maxwell combinó dos constantes medidas en experimentos de electrostática y de magnetismo, sin ninguna relación con la óptica, y le dio exactamente la velocidad de la luz. Esa coincidencia fue la prueba de que la luz es una onda electromagnética. Las cuatro ecuaciones Corriente de desplazamiento c Índice de refracción Línea de transmisión 01 Las cuatro Todo lo que apareció en las unidades anteriores —Gauss, la ausencia de monopolos, Faraday y Ampère— cabe en cuatro ecuaciones. Maxwell no las descubrió todas: las reunió, y al hacerlo notó que a una le faltaba un término. Gauss eléctrica, Gauss magnética, Faraday y Ampère-Maxwell. El…"},{"t":"Movimiento ondulatorio","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/movimiento-ondulatorio","x":"Física II · 120 h · Contenido 12 de 15 Movimiento ondulatorio Una señal recorriendo un cable es una onda, con su velocidad, su longitud de onda y sus reflexiones, y obedece la misma ecuación que una cuerda sacudida. De ahí sale toda la teoría de líneas de transmisión. Ecuación de onda Superposición Batido Estacionaria ROE 01 Qué viaja en una onda Una onda transporta energía y cantidad de movimiento, no materia. Las partículas del medio oscilan alrededor de su posición y se quedan donde estaban; lo que avanza es la perturbación. Eso vale para el sonido, para una cuerda y también para las señales de un cable. La ecuación de onda y su solución armónica. es el número de onda y la pulsación; el…"},{"t":"Ondas electromagnéticas","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/ondas-electromagneticas","x":"Física II · 120 h · Contenido 13 de 15 Ondas electromagnéticas Una carga quieta no radia y una que se mueve parejo, tampoco. Radia una carga acelerada, y una corriente alterna en un conductor es exactamente eso: de ahí sale toda la ingeniería de antenas. Poynting Campo cercano Friis Presupuesto de enlace Fotón 01 Cómo es una onda electromagnética De las ecuaciones de Maxwell en el vacío sale una onda con una estructura muy rígida: los dos campos son perpendiculares entre sí y los dos perpendiculares a la dirección de propagación. Es transversal, no necesita medio y sus dos campos oscilan en fase. El vector de Poynting da la potencia por unidad de área y apunta en la dirección de…"},{"t":"Polarización","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/polarizacion","x":"Física II · 120 h · Contenido 14 de 15 Polarización Dos polarizadores cruzados no dejan pasar nada. Al meter un tercero entre ellos pasa el 12,5 %, y agregar un filtro aumenta lo que pasa porque un polarizador no solo filtra: reorienta. Ley de Malus Polarización circular Brewster Birrefringencia LCD 01 La dirección en que oscila el campo Que la onda electromagnética sea transversal deja una libertad que las ondas longitudinales no tienen: el campo eléctrico puede oscilar en cualquier dirección del plano perpendicular a la propagación. Esa dirección es la polarización, y el sonido no la tiene porque oscila en la misma dirección en que avanza. Estado Qué hace el campo Cómo se logra Lineal…"},{"t":"Interferencia y difracción","d":"Tema · Física II","u":"/publicaciones/mapa-ingenieria/temas/interferencia-difraccion","x":"Física II · 120 h · Contenido 15 de 15 Interferencia y difracción La difracción no deja dibujar detalles mucho más chicos que la longitud de onda usada para dibujarlos. Por eso la industria del chip corrió de 436 nm a 13,5, y cada salto costó una fortuna. Young Coherencia Difracción Red de difracción Criterio de Rayleigh 01 Dos rendijas El experimento de Young es una de las evidencias más limpias de que la luz es una onda. Dos rendijas iluminadas por la misma fuente se comportan como dos emisores en fase, y en la pantalla no aparecen dos manchas sino una sucesión de franjas. La segunda expresión vale para ángulos chicos, que es lo habitual. Notar que la separación crece si las rendijas se…"},{"t":"Estadística descriptiva","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/estadistica-descriptiva","x":"Probabilidad y Estadística · 72 h · Contenido 1 de 6 Estadística descriptiva Un valor medido sin su dispersión no es una medición: es un número. Toda la estadística descriptiva de esta unidad existe para poder escribir el «más o menos» que va después del valor. Media y mediana Desvío estándar Cuartiles Histograma Valores atípicos 01 Por qué un solo número no alcanza Al medir diez veces la misma resistencia con el mismo instrumento no salen diez veces el mismo número. Esa dispersión no es un defecto del procedimiento: es información, y tirarla equivale a inventar una precisión que no se tiene. La estadística descriptiva resume un conjunto de datos con dos preguntas: alrededor de qué valor…"},{"t":"Probabilidad","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/probabilidad","x":"Probabilidad y Estadística · 72 h · Contenido 2 de 6 Probabilidad Un ensayo que acierta el 99 % de las veces, aplicado a un lote con 1 % de piezas falladas, da una pieza buena por cada pieza mala entre las que marca como defectuosas. No es un error del ensayo: es Bayes. Espacio muestral Condicional Independencia Bayes Falsos positivos 01 Tres axiomas y nada más Toda la teoría se levanta sobre tres reglas. Un experimento aleatorio tiene un conjunto de resultados posibles —el espacio muestral —, y a cada subconjunto de ese espacio, llamado suceso, se le asigna un número entre 0 y 1: De los tres sale todo lo demás por deducción, incluida la regla general : al sumar por separado, la…"},{"t":"Variables aleatorias y distribuciones","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/distribuciones","x":"Probabilidad y Estadística · 72 h · Contenido 3 de 6 Variables aleatorias y distribuciones El ruido térmico es normal, la llegada de fotones a un detector es Poisson y el tiempo hasta la falla de un componente es exponencial. Elegir mal la distribución da respuestas que parecen razonables y no lo son. Variable aleatoria Esperanza Normal Poisson Exponencial 01 De los sucesos a los números Una variable aleatoria es una función que le asigna un número a cada resultado del experimento. Ese paso, que parece burocrático, es el que permite calcular promedios, varianzas y todo lo demás: los sucesos no se suman, los números sí. Discreta Continua Valores Contables: 0, 1, 2… Todo un intervalo Se…"},{"t":"Inferencia y estimación","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/inferencia","x":"Probabilidad y Estadística · 72 h · Contenido 4 de 6 Inferencia y estimación «95 % de confianza» no significa que haya 95 % de probabilidad de que el valor esté en ese intervalo. El 95 % es una propiedad del procedimiento, no del intervalo que quedó, y esa distinción no se entiende leyéndola: hay que verla fallar. Población y muestra Error estándar Intervalo de confianza t de Student Tamaño de muestra 01 De la muestra a la población Nunca se mide todo. Se mide una muestra y se quiere decir algo sobre la población entera: el lote completo, todas las piezas que el proceso va a producir, el valor verdadero de la resistencia. Ese salto es la inferencia, y tiene reglas. Población Muestra Qué es…"},{"t":"Pruebas de hipótesis","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/pruebas-hipotesis","x":"Probabilidad y Estadística · 72 h · Contenido 5 de 6 Pruebas de hipótesis Mover el umbral de decisión reparte el riesgo entre los dos errores posibles, pero no lo reduce. Lo único que baja los dos a la vez es medir más, y cuál de los dos duele más es una decisión de ingeniería. Hipótesis nula Error tipo I y II Potencia Valor p Significación 01 Cómo se plantea una prueba Una prueba de hipótesis decide entre dos afirmaciones con datos. La estructura es siempre la misma y es deliberadamente asimétrica: se parte de suponer que no pasa nada y solo se abandona esa suposición si los datos la vuelven muy poco creíble. Qué afirma Su papel , nula No hay efecto, no hay diferencia Se sostiene salvo…"},{"t":"Análisis de regresión","d":"Tema · Probabilidad y Estadística","u":"/publicaciones/mapa-ingenieria/temas/regresion","x":"Probabilidad y Estadística · 72 h · Contenido 6 de 6 Análisis de regresión Cuatro conjuntos de datos pueden tener la misma recta, el mismo R² y la misma media, y no parecerse en nada. Eso es el cuarteto de Anscombe, y es la razón por la que un gráfico de residuos no es opcional. Mínimos cuadrados Calibración R² Residuos Anscombe 01 La recta que mejor pasa Medir la salida de un sensor a varias temperaturas conocidas da una nube de puntos, no una recta. La regresión busca la recta que mejor los representa, y «mejor» tiene una definición precisa: la que minimiza la suma de los cuadrados de las distancias verticales. Se minimizan las distancias verticales porque se supone que el error está en y…"},{"t":"Onda, propagación e interferencia","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/onda-interferencia","x":"Física Electrónica · 120 h · Contenido 1 de 9 Onda, propagación e interferencia Michelson construyó el instrumento más sensible de su época para medir el movimiento de la Tierra a través del éter, y no encontró nada. Ese resultado nulo es el punto de partida de toda la física del siglo XX. Interferencia Coherencia Michelson Éter Resultado nulo 01 Sin coherencia no hay interferencia Dos ondas se superponen siempre, pero para que el patrón de interferencia se vea hace falta que la relación de fase entre ellas se mantenga durante el tiempo de observación. Esa propiedad es la coherencia, y es lo que distingue un láser de una lámpara. Fuente Longitud de coherencia Qué permite Lámpara…"},{"t":"Radiación, electrón y rayos X","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/radiacion-electron","x":"Física Electrónica · 120 h · Contenido 2 de 9 Radiación, electrón y rayos X La física clásica predecía que un cuerpo caliente radiaría energía infinita en el ultravioleta. Para evitar ese absurdo, Planck supuso que la energía venía en paquetes, y él mismo consideró la idea un truco matemático. Cuerpo negro Catástrofe ultravioleta Planck Electrón Rayos X 01 La catástrofe ultravioleta Todo cuerpo caliente radia. La física del siglo XIX podía calcular cómo: se trataba la radiación dentro de una cavidad como un conjunto de modos, se le asignaba a cada uno la energía media que dicta la termodinámica clásica, y se sumaba. El resultado es la ley de Rayleigh-Jeans: Funciona bien en longitudes de…"},{"t":"Relatividad especial","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/relatividad","x":"Física Electrónica · 120 h · Contenido 3 de 9 Relatividad especial En un tubo de rayos catódicos de televisor los electrones viajan al 30 % de la velocidad de la luz, y el GPS se desincronizaría once kilómetros por día si no corrigiera los efectos relativistas. La relatividad no es un tema exótico: está en el aparato. Postulados Dilatación del tiempo Lorentz E = mc² GPS 01 Dos postulados y todo lo demás Einstein no agregó complicaciones: quitó una suposición. Ante el resultado nulo de Michelson-Morley, en lugar de inventar mecanismos para salvar el éter, lo declaró innecesario y postuló dos cosas. Postulado Dice Qué obliga a abandonar Relatividad Las leyes de la física son iguales en todo…"},{"t":"Efecto fotoeléctrico y dualidad","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/fotoelectrico","x":"Física Electrónica · 120 h · Contenido 4 de 9 Efecto fotoeléctrico y dualidad Einstein ganó el Nobel por esto, no por la relatividad. Una ecuación de una sola línea explicó tres hechos que la luz-onda no podía explicar, y de paso le dio nombre a la partícula que hoy cuenta un fotomultiplicador de a una. Fotón Función trabajo Millikan Compton Dualidad 01 El experimento que la onda no explica Luz sobre una placa metálica dentro de un tubo al vacío arranca electrones, que un colector recoge como corriente. Nada de eso sorprende a la teoría ondulatoria: una onda transporta energía y esa energía puede liberar cargas. Lo que la teoría ondulatoria no predice es cómo depende esa corriente de la luz…"},{"t":"De Broglie y el principio de incertidumbre","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/de-broglie","x":"Física Electrónica · 120 h · Contenido 5 de 9 De Broglie y el principio de incertidumbre Si un fotón puede comportarse como partícula, un electrón puede comportarse como onda. De esa simetría salió media mecánica cuántica, y también la razón por la que un átomo no colapsa sobre sí mismo. De Broglie Davisson-Germer Incertidumbre Energía de punto cero Microscopio electrónico 01 La hipótesis de de Broglie El fotón tiene cantidad de movimiento sin tener masa: , la relación que cerró la unidad anterior. En 1924 Louis de Broglie dio vuelta la pregunta: si una onda —la luz— se comporta como partícula, ¿por qué no podría una partícula —un electrón, un átomo, cualquier cosa con masa— comportarse…"},{"t":"Mecánica cuántica: escalón, barrera y pozo","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/mecanica-cuantica","x":"Física Electrónica · 120 h · Contenido 6 de 9 Mecánica cuántica: escalón, barrera y pozo Un electrón puede aparecer del otro lado de una pared que, según toda la física clásica, no debería poder cruzar. Ese resultado no es una curiosidad de laboratorio: es la razón por la que un chip no se puede adelgazar más allá de cierto límite. Schrödinger Efecto túnel Pozo infinito Oscilador armónico MOSFET 01 La ecuación que reemplaza a Newton Si una partícula es también una onda, tiene que existir una ecuación que gobierne esa onda, igual que la segunda ley de Newton gobierna una trayectoria. Esa ecuación la escribió Schrödinger en 1926, apoyándose directamente en la hipótesis de de Broglie del…"},{"t":"Modelos atómicos y Schrödinger","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/modelos-atomicos","x":"Física Electrónica · 120 h · Contenido 7 de 9 Modelos atómicos y Schrödinger El electromagnetismo clásico predice que ningún átomo puede durar más de dieciséis picosegundos. Resolver esa contradicción llevó de Bohr a Schrödinger a Pauli, y terminó explicando por qué un cristal tiene bandas de energía en lugar de niveles sueltos. Bohr Schrödinger Números cuánticos Pauli Bandas de energía 01 El átomo que la física clásica no podía sostener El experimento de dispersión de Rutherford (1911) —partículas alfa contra una lámina de oro, con algunas rebotando hacia atrás— tiró abajo el modelo del «budín de pasas» de Thomson y dejó un átomo con casi toda su masa y toda su carga positiva concentrada…"},{"t":"Mecánica estadística clásica y cuántica","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/mecanica-estadistica","x":"Física Electrónica · 120 h · Contenido 8 de 9 Mecánica estadística clásica y cuántica La teoría clásica de los electrones en un metal fallaba por casi dos órdenes de magnitud, y tardó veintisiete años en saberse por qué: Pauli les prohíbe a casi todos moverse. El nivel de Fermi que sale de ahí es la idea central de la unidad que cierra esta materia. Fermi-Dirac Nivel de Fermi Bose-Einstein Maxwell-Boltzmann Termoiónica 01 Por qué hace falta una física estadística Un centímetro cúbico de cobre tiene del orden de electrones libres. Ni la mecánica de Newton ni la ecuación de Schrödinger están pensadas para seguirle la pista a cada uno: hace falta una descripción que diga, en cambio, qué…"},{"t":"Física de semiconductores","d":"Tema · Física Electrónica","u":"/publicaciones/mapa-ingenieria/temas/fisica-semiconductores","x":"Física Electrónica · 120 h · Contenido 9 de 9 Física de semiconductores Cada contenido de esta materia dejó una pieza servida para este: el fotón, el efecto túnel, la estadística de Fermi-Dirac, el principio de Pauli. Acá se arman todas juntas en la banda prohibida y el nivel de Fermi, que son de donde sale un diodo. Banda prohibida Masa efectiva Ley de acción de masas Nivel de Fermi Silicio 01 De los niveles atómicos a las bandas La unidad de los modelos atómicos terminó con una idea pendiente: cuando átomos se juntan en un cristal, Pauli obliga a que el nivel atómico único de cada uno se desdoble en tantos niveles como átomos hay, tan pegados entre sí que forman una banda continua de…"},{"t":"Agencia, tiempos verbales y subordinación","d":"Tema · Inglés I","u":"/publicaciones/mapa-ingenieria/temas/dimension-linguistica","x":"Inglés I · 48 h · Contenido 1 de 3 Agencia, tiempos verbales y subordinación Casi ningún datasheet dice «the engineer connects the resistor». Dice «the resistor is connected», sin agente. Aprender a leer esa ausencia a propósito es la mitad de esta unidad. Voz pasiva Nominalización Verbos modales Subordinación Vocabulario técnico 01 Leer inglés técnico no es lo mismo que hablarlo El plan de estudios llama a esto «dimensión lingüística», y el objetivo concreto es otro: no es hablar inglés con fluidez, es leer un datasheet, un paper o una norma técnica con comprensión real. Son habilidades distintas. Un texto técnico en inglés usa una gramática mucho más restringida y repetitiva que el habla…"},{"t":"Géneros discursivos y cohesión textual","d":"Tema · Inglés I","u":"/publicaciones/mapa-ingenieria/temas/dimension-discursiva","x":"Inglés I · 48 h · Contenido 2 de 3 Géneros discursivos y cohesión textual Un abstract de IEEE tiene siempre la misma estructura en cuatro oraciones. Reconocerla de entrada ahorra la mitad del esfuerzo de lectura, antes de entender una sola palabra. Géneros discursivos Abstract Conectores Cohesión Referencia 01 Los géneros que un ingeniero realmente lee Un género discursivo es un tipo de texto con una estructura fija que sus lectores dan por sabida. No hace falta leer un datasheet entero para saber dónde va a estar cada cosa: la estructura se repite de un fabricante a otro, y conocerla de antemano es la estrategia de lectura más rentable de toda esta materia. Género Estructura típica Qué…"},{"t":"Estrategias de lectura y traducción técnica","d":"Tema · Inglés I","u":"/publicaciones/mapa-ingenieria/temas/dimension-estrategica","x":"Inglés I · 48 h · Contenido 3 de 3 Estrategias de lectura y traducción técnica «Actually» no es actualmente y «library» no es librería. En un texto técnico esos falsos amigos arruinan la comprensión más rápido que cualquier palabra desconocida. Paratexto Falsos amigos Cognados Formación de palabras Traducción técnica 01 Leer antes de leer: el paratexto El paratexto es todo lo que rodea al texto principal —título, subtítulos, figuras, tablas, notas al pie, el resumen— y se puede aprovechar antes de descifrar una sola oración. En un texto técnico, el paratexto suele contener la mitad de la información útil. Elemento paratextual Qué anticipa Título y subtítulos El tema exacto y cómo se…"},{"t":"Constantes concentradas e invariantes","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/modelos-concentrados","x":"Teoría de los Circuitos I · 144 h · Contenido 1 de 13 Constantes concentradas e invariantes Todo circuito es, en el fondo, un problema de ondas electromagnéticas. El modelo de constantes concentradas es la aproximación que permite ignorar eso, y saber cuándo deja de valer es tan importante como saber usarla. Constantes concentradas Regla de λ/10 Invariancia temporal Resonancia propia Modelo ideal 01 Todo circuito es, en el fondo, un problema de ondas Las ecuaciones de Maxwell no distinguen entre un cable y una antena: cualquier conductor con corriente variable irradia y propaga campos a la velocidad de la luz. Resolver un circuito de esa manera —campo por campo, punto por punto del espacio—…"},{"t":"Señales en la teoría de los circuitos","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/senales-circuitos","x":"Teoría de los Circuitos I · 144 h · Contenido 2 de 13 Señales en la teoría de los circuitos Un multímetro común mide mal casi cualquier señal que no sea una senoidal pura, y la mayoría de las señales de la electrónica de potencia no lo son. La diferencia entre valor medio y valor eficaz explica por qué. Clasificación de señales Señales elementales Valor eficaz (RMS) Factor de forma Señales de energía y potencia 01 Clasificar una señal antes de analizarla Antes de resolver cualquier circuito hace falta saber qué tipo de señal lo excita, porque cada tipo admite herramientas distintas. Cuatro clasificaciones ordenan casi todo lo que sigue en esta materia: Clasificación Distingue Ejemplo…"},{"t":"Componentes pasivos: frecuencia y tiempo","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/componentes-pasivos","x":"Teoría de los Circuitos I · 144 h · Contenido 3 de 13 Componentes pasivos: frecuencia y tiempo El mismo inductor es casi un cortocircuito a 50 Hz y casi un circuito abierto a 1 MHz. La impedancia compleja explica por qué, y la constante de tiempo RC explica todo lo que pasa en el instante en que se cierra una llave. Fasores Impedancia Constante de tiempo Régimen permanente Transitorio RC 01 La relación tensión-corriente de cada componente Tres elementos pasivos alcanzan para armar casi cualquier circuito lineal. Cada uno relaciona tensión y corriente de una manera distinta, y esa diferencia es la que hace interesante a toda esta materia. Componente Relación v-i ¿Tiene memoria? Energía que…"},{"t":"Régimen sinusoidal y el plano s","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/regimen-sinusoidal","x":"Teoría de los Circuitos I · 144 h · Contenido 4 de 13 Régimen sinusoidal y el plano s La ganancia de un filtro a cualquier frecuencia se puede medir con una regla sobre un dibujo: es la distancia entre un punto del eje imaginario y el polo. El plano s convierte la respuesta en frecuencia en geometría. Plano s Polos y ceros Bode Decibeles Factor de potencia 01 La frecuencia compleja El contenido anterior usó para convertir derivadas en productos. Ese es un caso particular de algo más general: la frecuencia compleja . Una señal de la forma abarca de un solo golpe todas las señales elementales de la unidad de señales: Valor de Señal Una constante: continua pura real negativo Una exponencial…"},{"t":"Lugares geométricos de impedancia y admitancia","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/lugares-geometricos","x":"Teoría de los Circuitos I · 144 h · Contenido 5 de 13 Lugares geométricos de impedancia y admitancia Una recta infinita en el plano de impedancias se convierte en un arco de circunferencia finito en el de admitancias. Con esa sola propiedad se predijo durante décadas el comportamiento de un motor con regla y compás, y de ella sale la carta de Smith. Lugar geométrico Inversión compleja Admitancia Diagrama circular Carta de Smith 01 Qué es un lugar geométrico La impedancia de un circuito es un número complejo: un punto del plano. Si uno de sus parámetros cambia —la frecuencia, una resistencia ajustable, la carga de un motor—, ese punto se mueve y dibuja una curva. Esa curva es el lugar…"},{"t":"Resonancia","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/resonancia","x":"Teoría de los Circuitos I · 144 h · Contenido 6 de 13 Resonancia Con una fuente de 10 V, sobre el capacitor de un circuito resonante pueden aparecer mil. El mismo fenómeno sintoniza una radio, fija la hora de un reloj de cuarzo y alimenta una tarjeta SUBE sin pila. Resonancia Factor de calidad Ancho de banda Sintonía Cuarzo 01 La resonancia serie En un circuito RLC serie la reactancia inductiva crece con la frecuencia y la capacitiva cae. Hay una única frecuencia en que las dos se igualan y se cancelan: la frecuencia de resonancia. Ahí la impedancia queda reducida a , su mínimo, y la corriente llega a su máximo. En resonancia la fuente «ve» una resistencia pura: tensión y corriente quedan…"},{"t":"Régimen permanente y espectros","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/regimen-espectros","x":"Teoría de los Circuitos I · 144 h · Contenido 7 de 13 Régimen permanente y espectros Un filtro no deforma una señal de manera misteriosa: cambia la proporción entre sus armónicos. Con esa sola idea, todo lo aprendido para senoidales sirve para cualquier señal periódica. Serie de Fourier Espectro Armónicos Parseval THD 01 Cualquier señal periódica es una suma de senoidales Todo lo que se aprendió para el régimen sinusoidal parecería servir solo para señales senoidales puras, que en la práctica casi no existen. Fourier resolvió el problema en 1807: toda señal periódica razonable es una suma de senoidales cuyas frecuencias son múltiplos enteros de la fundamental. Como los circuitos lineales…"},{"t":"Respuesta transitoria y residuos","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/respuesta-transitoria","x":"Teoría de los Circuitos I · 144 h · Contenido 8 de 13 Respuesta transitoria y residuos Antes de hacer una sola cuenta, la ubicación de los polos ya dice si un circuito va a oscilar, cuánto va a tardar en asentarse y si va a pasarse de largo. Los residuos solo ponen los números. Laplace Residuos Polos Amortiguamiento Sobrepico 01 El circuito entero pasado a El régimen permanente se resolvía con fasores. El transitorio —lo que pasa desde que se cierra una llave hasta que el circuito se asienta— se resuelve con la transformada de Laplace, que hace con las derivadas lo mismo que los fasores pero sin exigir que la señal sea senoidal ni que haya pasado mucho tiempo. Además incorpora de manera…"},{"t":"Resolución sistemática de circuitos","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/resolucion-sistematica","x":"Teoría de los Circuitos I · 144 h · Contenido 9 de 13 Resolución sistemática de circuitos Basta una resistencia en diagonal para que un circuito deje de reducirse en serie y paralelo. El método de nodos lo resuelve igual, y es exactamente lo que hace por dentro cualquier simulador de circuitos. Nodos Mallas Matriz de conductancias Puente de Wheatstone SPICE 01 Cuando serie y paralelo no alcanzan Mientras un circuito se deja reducir combinando resistencias en serie y en paralelo, alcanza con eso. Pero basta un elemento que conecte dos ramas «en diagonal» para que no quede ningún par de resistencias estrictamente en serie ni en paralelo. El ejemplo clásico es el puente de Wheatstone con un…"},{"t":"Teoremas de los circuitos","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/teoremas-circuitos","x":"Teoría de los Circuitos I · 144 h · Contenido 10 de 13 Teoremas de los circuitos Visto desde dos bornes, cualquier circuito lineal es una fuente con una resistencia en serie, y no hay experimento que lo distinga. Por qué una antena se adapta a 50 Ω y un parlante no, sale de ahí. Superposición Thévenin Norton Máxima potencia Adaptación 01 Superposición En un circuito lineal con varias fuentes independientes, cualquier tensión o corriente es la suma de las que produciría cada fuente actuando sola. Para «apagar» una fuente se la reemplaza por lo que vale cuando entrega cero: una fuente de tensión, por un cortocircuito; una de corriente, por un circuito abierto. La potencia no se superpone…"},{"t":"Circuitos acoplados inductivamente","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/circuitos-acoplados","x":"Teoría de los Circuitos I · 144 h · Contenido 11 de 13 Circuitos acoplados inductivamente Dos bobinas sin ningún cable entre ellas transfieren energía, aíslan un circuito de la red y convierten un parlante de 8 Ω en una carga de 5 kΩ. Todo sale de un solo número: la inductancia mutua. Inductancia mutua Acoplamiento Transformador ideal Impedancia reflejada Dispersión 01 Inductancia mutua Cuando el flujo magnético de una bobina atraviesa a otra, una corriente variable en la primera induce tensión en la segunda sin que haya ninguna conexión eléctrica entre ellas. Esa relación se mide con la inductancia mutua , y agrega un término a la ecuación de cada bobina: es el coeficiente de acoplamiento:…"},{"t":"Circuitos polifásicos","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/circuitos-polifasicos","x":"Teoría de los Circuitos I · 144 h · Contenido 12 de 13 Circuitos polifásicos Cuando se corta el neutro de un edificio, algunos departamentos reciben más de 300 V y se les queman los artefactos. El diagrama fasorial de una estrella desequilibrada explica exactamente por qué. Trifásica Estrella y triángulo Neutro Millman Potencia trifásica 01 Tres tensiones desfasadas 120° Un generador trifásico tiene tres bobinados separados 120° en el espacio, y produce tres tensiones de igual amplitud desfasadas 120° en el tiempo. Toda la red eléctrica del mundo se genera, transporta y distribuye así, por tres razones que se ven en esta unidad: con tres conductores se transporta el triple de potencia que…"},{"t":"Resolución por variables de estado","d":"Tema · Teoría de los Circuitos I","u":"/publicaciones/mapa-ingenieria/temas/variables-estado","x":"Teoría de los Circuitos I · 144 h · Contenido 13 de 13 Resolución por variables de estado Un simulador puede mostrar un circuito que oscila y crece sin límite cuando el circuito real se asienta tranquilo. La forma de estado explica cómo simula un simulador, y por qué a veces se equivoca. Variables de estado Matriz A Plano de fases Euler Runge-Kutta 01 Qué es el estado de un circuito Para predecir qué va a hacer un circuito desde un instante en adelante no hace falta conocer toda su historia: alcanza con saber cuánta energía guarda cada elemento que puede guardarla. Esa información mínima es el estado, y en un circuito eléctrico tiene una elección natural: las tensiones de los capacitores y…"},{"t":"Lógica combinacional: minimización y riesgos","d":"Tema · Técnicas Digitales I","u":"/publicaciones/mapa-ingenieria/temas/combinacional-minimizacion","x":"Técnicas Digitales I · 96 h · Contenido 1 de 4 Lógica combinacional: minimización y riesgos La expresión más corta no siempre es la mejor: puede dejar caer la salida durante unos nanosegundos cuando no debería. Minimizar bien es encontrar la mínima y saber cuándo agregarle un término. Karnaugh Quine-McCluskey Indiferentes Riesgos Camino crítico 01 De la tabla de verdad a la expresión mínima Las compuertas, el álgebra de Boole y el paso de una tabla de verdad a un circuito están desarrollados en la página de lógica combinacional de la tecnicatura . Esta unidad parte de ahí y se hace la pregunta de ingeniería: entre todos los circuitos que implementan la misma función, ¿cuál es el mejor?…"},{"t":"Lógica secuencial: máquinas de estado y temporización","d":"Tema · Técnicas Digitales I","u":"/publicaciones/mapa-ingenieria/temas/maquinas-estado","x":"Técnicas Digitales I · 96 h · Contenido 2 de 4 Lógica secuencial: máquinas de estado y temporización Un equipo que se cuelga una vez por día sin causa aparente puede tener un flip-flop que lee un pulsador sin sincronizar. Agregarle un segundo flip-flop lleva esa falla a una vez cada decenas de miles de años. Moore y Mealy Diseño sincrónico Camino crítico Metaestabilidad Sincronizador 01 El diseño sincrónico Flip-flops, contadores y registros de desplazamiento están desarrollados en la página de lógica secuencial de la tecnicatura . Esta unidad sube un nivel: cómo se diseña un sistema secuencial cualquiera y qué lo limita. Casi toda la lógica digital moderna es sincrónica: un único reloj…"},{"t":"Lenguajes descriptores de hardware","d":"Tema · Técnicas Digitales I","u":"/publicaciones/mapa-ingenieria/temas/lenguajes-hdl","x":"Técnicas Digitales I · 96 h · Contenido 3 de 4 Lenguajes descriptores de hardware En Verilog, cambiar un « VHDL Verilog Concurrencia Asignación no bloqueante Síntesis 01 Describir hardware, no programarlo Un lenguaje descriptor de hardware (HDL) se parece a un lenguaje de programación y no es uno. Un programa en C es una lista de instrucciones que un procesador ejecuta de a una, en orden. Una descripción en VHDL o Verilog es la descripción de un circuito: cada sentencia es un pedazo de hardware que existe y funciona al mismo tiempo que todos los demás. No hay un «ahora se ejecuta esta línea»; hay compuertas y flip-flops que reaccionan todos a la vez a sus entradas. Ese cambio de mentalidad…"},{"t":"Dispositivos lógicos programables","d":"Tema · Técnicas Digitales I","u":"/publicaciones/mapa-ingenieria/temas/logica-programable","x":"Técnicas Digitales I · 96 h · Contenido 4 de 4 Dispositivos lógicos programables Dentro de una FPGA no hay compuertas AND ni OR: hay memorias de 16 o 64 bits que guardan tablas de verdad. Una AND y la función más enredada de seis variables ocupan lo mismo. PAL y GAL CPLD FPGA LUT Bitstream 01 Del circuito fijo al programable Con compuertas sueltas de la serie 74, cada cambio del diseño es una placa nueva. Un dispositivo lógico programable (PLD) invierte el orden: el fabricante vende un integrado con muchos recursos lógicos genéricos sin conectar, y quien diseña decide después, con un archivo de configuración, qué función cumple cada uno y cómo se conectan entre sí. El mismo chip puede ser…"},{"t":"Teoría básica de semiconductores: transporte de portadores","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/transporte-portadores","x":"Dispositivos Electrónicos · 120 h · Contenido 1 de 9 Teoría básica de semiconductores: transporte de portadores Una oblea de silicio con un átomo de fósforo cada diez millones conduce más de cien mil veces mejor que el silicio puro. Todo dispositivo nace de controlar cuántos portadores hay y cómo se mueven. Deriva Movilidad Difusión Relación de Einstein Recombinación 01 Del material al dispositivo La página de física de los semiconductores dejó establecido cuántos portadores hay: la concentración intrínseca , del orden de cm⁻³ en el silicio a temperatura ambiente, la ley de acción de masas y cómo el dopaje fija una de las dos concentraciones. Un dispositivo, en cambio, se define por cómo se…"},{"t":"Juntura PN y diodos","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/juntura-pn","x":"Dispositivos Electrónicos · 120 h · Contenido 2 de 9 Juntura PN y diodos Un diodo de 1000 V y uno Zener de 3 V son la misma juntura PN con distinto dopaje. Lo que decide cuánta tensión aguanta es el lado menos dopado, no el más. Zona de agotamiento Ecuación de Shockley Capacidad de juntura Ruptura Recuperación inversa 01 La juntura en equilibrio Al unir una región P con una N, los huecos del lado P se difunden hacia el N y los electrones del N hacia el P, siguiendo el gradiente de concentración de la unidad anterior . Cada portador que cruza deja atrás un ion fijo sin compensar: aceptores negativos del lado P, donadores positivos del lado N. Esa carga fija crea un campo eléctrico que se…"},{"t":"Transistor bipolar: continua, señal y conmutación","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/bjt-dispositivo","x":"Dispositivos Electrónicos · 120 h · Contenido 3 de 9 Transistor bipolar: continua, señal y conmutación Todos los transistores bipolares del mundo tienen la misma transconductancia a 1 mA: 38,7 mS. La β, en cambio, varía de 100 a 300 entre dos ejemplares del mismo tipo. Ebers-Moll Efecto Early Híbrido π Saturación Carga almacenada 01 Dos junturas muy cerca Un transistor bipolar NPN son dos junturas PN espalda con espalda, pero no es lo mismo que dos diodos: su gracia es que la base del medio es mucho más delgada que la longitud de difusión de los electrones. Con la juntura base-emisor en directa, el emisor inyecta electrones en la base; casi ninguno llega a recombinarse, y al alcanzar el…"},{"t":"JFET: continua, señal y conmutación","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/jfet","x":"Dispositivos Electrónicos · 120 h · Contenido 4 de 9 JFET: continua, señal y conmutación Dos 2N5457 de la misma bolsa, en el mismo circuito, pueden conducir 0,4 y 2,9 mA. El JFET es el transistor de menor ruido con fuentes de alta impedancia, y también el más disperso. Estrangulamiento Ecuación de Shockley Autopolarización Dispersión Llave analógica 01 Un canal que se estrangula El transistor de efecto de campo de juntura (JFET) es la idea más directa de controlar una corriente con una tensión. Un canal de silicio tipo N une dos terminales, drenador y fuente, y a los costados tiene regiones P⁺ unidas entre sí que forman la compuerta. La juntura compuerta-canal se polariza en inversa, y su…"},{"t":"Transistor MOS: canal largo, canal corto y escalado","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/mosfet-escalado","x":"Dispositivos Electrónicos · 120 h · Contenido 5 de 9 Transistor MOS: canal largo, canal corto y escalado Con un canal de 30 nm, la fórmula de libro del MOS predice cinco veces más corriente de la que el transistor da. Y la alimentación de los procesadores no baja de 0,7 V por un límite de la termodinámica: 60 mV por década. Tensión umbral Canal corto Saturación de velocidad Escalado de Dennard FinFET 01 El capacitor MOS y la inversión El transistor MOS es un capacitor con un semiconductor como una de sus placas: una compuerta conductora, un óxido delgadísimo y un sustrato de silicio tipo P. Una tensión positiva en la compuerta primero empuja a los huecos lejos de la superficie (agotamiento)…"},{"t":"Inversor CMOS","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/inversor-cmos","x":"Dispositivos Electrónicos · 120 h · Contenido 6 de 9 Inversor CMOS Dos transistores, uno siempre apagado: esa es la razón por la que un procesador con miles de millones de compuertas puede funcionar sin derretirse. Transferencia Umbral de conmutación Márgenes de ruido Potencia dinámica Latch-up 01 Dos transistores complementarios El inversor CMOS es un PMOS entre la alimentación y la salida y un NMOS entre la salida y masa, con las dos compuertas unidas a la entrada. Con la entrada en 0, el PMOS conduce y el NMOS está apagado: la salida queda en . Con la entrada en , al revés. En cualquiera de los dos estados uno de los dos transistores está apagado y no hay camino de corriente entre la…"},{"t":"Memorias CMOS","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/memorias-cmos","x":"Dispositivos Electrónicos · 120 h · Contenido 7 de 9 Memorias CMOS Un bit de la memoria principal son unos 150 000 electrones en un capacitor que pierde. Si nadie los repone, en menos de un segundo el 1 se lee como 0. SRAM DRAM Flash Refresco Reparto de carga 01 Tres maneras de guardar un bit Toda la memoria de una computadora actual está hecha con transistores MOS, pero de tres maneras muy distintas, cada una con un compromiso diferente entre velocidad, densidad y permanencia: SRAM DRAM Flash Cómo guarda el bit Dos inversores realimentados Carga en un capacitor Carga atrapada en la compuerta de un transistor Transistores por bit 6 1 más un capacitor 1, y varios bits por transistor Área de…"},{"t":"Dispositivos multijuntura: tiristores e IGBT","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/multijunturas","x":"Dispositivos Electrónicos · 120 h · Contenido 8 de 9 Dispositivos multijuntura: tiristores e IGBT Un pulso de microsegundos en la compuerta y el tiristor queda conduciendo solo hasta el próximo cruce por cero. Es el mismo mecanismo que, sin que nadie lo quiera, funde un circuito CMOS en el latch-up. Tiristor TRIAC Control de fase IGBT Enclavamiento 01 Cuatro capas, tres junturas Un tiristor (o SCR, rectificador controlado de silicio) es una estructura PNPN: ánodo P, una N liviana y ancha que soporta la tensión, una P que lleva el terminal de compuerta, y un cátodo N. Tiene tres junturas en serie, y con el ánodo positivo la del medio queda en inversa y bloquea. Hasta ahí parece un diodo que…"},{"t":"Fotónica y optoelectrónica","d":"Tema · Dispositivos Electrónicos","u":"/publicaciones/mapa-ingenieria/temas/optoelectronica","x":"Dispositivos Electrónicos · 120 h · Contenido 9 de 9 Fotónica y optoelectrónica El silicio detecta la luz muy bien y casi no la emite: su banda prohibida es indirecta. Por eso las celdas solares son de silicio y los LED, de galio. Fotodiodo Celda solar LED Láser Optoacoplador 01 Fotones y bandas Un fotón de energía mayor que la banda prohibida puede ser absorbido y crear un par electrón-hueco; un par que se recombina puede emitir un fotón con la energía de la banda prohibida. Toda la optoelectrónica sale de esas dos frases y de la relación entre energía y longitud de onda: El silicio, con 1,12 eV, absorbe hasta unos 1100 nm; el GaAs, con 1,42 eV, emite a 870 nm; el GaN, con 3,4 eV, en el…"},{"t":"Legislación: el derecho alrededor de la ingeniería","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/legislacion-introduccion","x":"Legislación · 48 h · Contenido 1 de 13 Legislación: el derecho alrededor de la ingeniería Cada firma de un ingeniero tiene consecuencias jurídicas: un informe, un contrato, un plano, una pericia. El derecho no es un tema ajeno a la profesión, es el marco en el que se ejerce. Norma jurídica Norma técnica Fuentes del derecho InfoLEG Ejercicio profesional 01 Por qué un ingeniero estudia derecho Casi todo lo que hace un ingeniero en su trabajo tiene un lado jurídico, aunque no lo parezca. Aceptar un presupuesto es celebrar un contrato. Firmar un plano de una instalación es asumir una responsabilidad que puede durar años. Contratar a un técnico es entrar en una relación laboral con reglas…"},{"t":"Derecho público y derecho privado","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/derecho-publico-privado","x":"Legislación · 48 h · Contenido 2 de 13 Derecho público y derecho privado Un contrato con una empresa y una licitación del Estado pueden pedir el mismo equipo y regirse por reglas muy distintas. La diferencia está en quién está del otro lado. Derecho público Derecho privado Personas Actos jurídicos Código Civil y Comercial 01 Qué es el derecho El derecho es el conjunto de normas que regulan la conducta de las personas en sociedad y que el Estado puede hacer cumplir por la fuerza si hace falta. Esa última parte lo distingue de la moral, de las reglas de cortesía o de una norma técnica: una norma jurídica tiene detrás un aparato —jueces, policía, organismos de control— capaz de imponer una…"},{"t":"La Constitución Nacional","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/constitucion-nacional","x":"Legislación · 48 h · Contenido 3 de 13 La Constitución Nacional El derecho a ejercer una profesión, a la propiedad de un invento o a un ambiente sano no los da una ley: están en la Constitución, y ninguna ley los puede anular. Supremacía Federalismo Derechos y garantías Artículo 14 bis Amparo 01 La ley de leyes La Constitución Nacional es la norma que organiza el Estado y fija los derechos de los habitantes. Fue sancionada en 1853 y reformada en 1860, 1866, 1898, 1957 y 1994. La reforma de 1994 fue la más extensa: agregó los derechos al ambiente sano y de los consumidores, la acción de amparo, el Consejo de la Magistratura y la jerarquía constitucional de una serie de tratados de derechos…"},{"t":"El sistema normativo argentino","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/sistema-normativo","x":"Legislación · 48 h · Contenido 4 de 13 El sistema normativo argentino Una ordenanza municipal no puede contradecir una ley nacional, y una norma IRAM no obliga a nadie hasta que una norma jurídica la hace obligatoria. Saber qué manda sobre qué evita muchos errores. Pirámide normativa Leyes y decretos Vigencia Provincias y municipios Normas IRAM 01 La pirámide de normas Las normas jurídicas no están todas al mismo nivel. Forman un orden escalonado, que el jurista Hans Kelsen describió como una pirámide: cada norma encuentra su validez en una superior y no puede contradecirla. Cuando dos normas chocan, la de rango más alto prevalece. En el orden nacional argentino, de arriba hacia abajo:…"},{"t":"Sociedades","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/sociedades-comerciales","x":"Legislación · 48 h · Contenido 5 de 13 Sociedades Dos ingenieros que arman una empresa sin constituirla responden con su patrimonio personal por las deudas del negocio. Elegir el tipo de sociedad es elegir cuánto se arriesga. Ley General de Sociedades SRL SA SAS Responsabilidad de los socios 01 Qué es una sociedad Según el artículo 1 de la Ley General de Sociedades (ley 19.550), hay sociedad cuando una o más personas, organizadas según uno de los tipos que la ley prevé, se obligan a hacer aportes para producir o intercambiar bienes o servicios, participando de los beneficios y soportando las pérdidas. La sociedad es una persona jurídica distinta de sus socios, con patrimonio propio:…"},{"t":"Contratos","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/contratos","x":"Legislación · 48 h · Contenido 6 de 13 Contratos Un presupuesto aceptado por correo electrónico ya es un contrato. Lo que no se escribió lo completa la ley, y no siempre como uno esperaba. Consentimiento Buena fe Contrato de obra Contrato de servicios Confidencialidad 01 Qué es un contrato El artículo 957 del Código Civil y Comercial define el contrato como el acto jurídico por el cual dos o más partes manifiestan su consentimiento para crear, regular, modificar, transferir o extinguir relaciones jurídicas patrimoniales. Tres principios lo gobiernan: Libertad de contratación (artículo 958): las partes deciden si contratan, con quién y con qué contenido, dentro de los límites de la ley, el…"},{"t":"Derecho laboral","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/derecho-laboral","x":"Legislación · 48 h · Contenido 7 de 13 Derecho laboral La misma tarea, hecha por un ingeniero empleado o por uno que factura como autónomo, tiene reglas completamente distintas. Lo que decide cuál rige es la realidad del vínculo, no lo que dice el papel. Ley de Contrato de Trabajo Relación de dependencia Indemnización Convenios colectivos Riesgos del trabajo 01 Empleado o independiente Un ingeniero puede trabajar de dos maneras muy distintas para el derecho. En relación de dependencia, pone su trabajo a disposición de un empleador que lo organiza y lo dirige, a cambio de una remuneración: rige la Ley de Contrato de Trabajo (ley 20.744) y el convenio colectivo que corresponda. Como…"},{"t":"El ejercicio profesional de la ingeniería","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/ejercicio-profesional","x":"Legislación · 48 h · Contenido 8 de 13 El ejercicio profesional de la ingeniería El título de la universidad no alcanza para firmar: hace falta la matrícula del consejo o colegio de la jurisdicción donde se trabaja. Título habilitante Actividades reservadas Matrícula Consejos profesionales COPITEC 01 Del título a la firma Recibirse no alcanza para firmar. Entre el título universitario y el primer plano firmado hay dos pasos que regula el derecho: El título habilitante, expedido por una universidad con una carrera acreditada, que define para qué está capacitado el graduado. La matrícula en el consejo o colegio profesional de la jurisdicción donde se va a trabajar, que habilita a ejercer y…"},{"t":"La ética en el ejercicio profesional","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/etica-profesional","x":"Legislación · 48 h · Contenido 9 de 13 La ética en el ejercicio profesional Casi todas las faltas de ética profesional son legales hasta que alguien se lastima. Los códigos existen para decidir antes. Deontología Código de ética Conflicto de interés Secreto profesional Tribunal de ética 01 Ética, moral y deontología La moral es el conjunto de convicciones de una persona o una comunidad sobre lo que está bien y lo que está mal. La ética es la reflexión sobre esas convicciones: por qué algo está bien, cómo decidir cuando dos deberes chocan. La deontología profesional es la ética aplicada a una profesión, escrita en reglas concretas que una comunidad profesional se da a sí misma y que un…"},{"t":"Derechos y deberes legales del profesional","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/derechos-deberes-profesional","x":"Legislación · 48 h · Contenido 10 de 13 Derechos y deberes legales del profesional La firma habilita y obliga a la vez: el mismo acto que le da valor legal a un plano convierte a quien firma en responsable de lo que dice. Firma profesional Honorarios Deber de información Secreto profesional Propiedad intelectual 01 La firma habilita y obliga La matrícula le da al ingeniero un conjunto de derechos que el resto de las personas no tiene, y a cambio le impone deberes más exigentes. Las dos cosas se concentran en el mismo acto: la firma. Un plano, un certificado o un informe firmado por un matriculado tiene valor legal porque alguien calificado responde por él. La unidad de ejercicio profesional…"},{"t":"Actividad pericial y arbitraje","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/actividad-pericial","x":"Legislación · 48 h · Contenido 11 de 13 Actividad pericial y arbitraje El juez sabe derecho, no electrónica. Cuando un pleito depende de si un equipo falló por diseño o por mal uso, lo decide en gran parte el informe de un perito. Perito de oficio Consultor técnico Informe pericial Arbitraje Amigable componedor 01 El perito, los ojos técnicos del juez Muchos pleitos dependen de una cuestión técnica: si un incendio empezó en un tablero mal protegido, si un equipo médico falló por diseño o por mal uso, si una instalación cumple lo contratado. El juez sabe derecho, no electrónica. Cuando la decisión requiere conocimientos especiales de una ciencia o una técnica, se ordena una prueba pericial,…"},{"t":"Responsabilidad profesional: civil, administrativa y penal","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/responsabilidad-profesional","x":"Legislación · 48 h · Contenido 12 de 13 Responsabilidad profesional: civil, administrativa y penal Un mismo accidente puede terminar con el ingeniero pagando una indemnización, suspendido en la matrícula y procesado penalmente. Son tres vías independientes. Responsabilidad civil Factor de atribución Responsabilidad disciplinaria Delito culposo Prescripción 01 Tres responsabilidades independientes Cuando algo sale mal en un trabajo firmado por un ingeniero, puede responder por tres vías a la vez, cada una con su finalidad, sus reglas y su tribunal: Civil Administrativa y disciplinaria Penal Finalidad Reparar el daño causado Sancionar la falta a las normas de la profesión o de un organismo…"},{"t":"Legislación sobre obras","d":"Tema · Legislación","u":"/publicaciones/mapa-ingenieria/temas/legislacion-obras","x":"Legislación · 48 h · Contenido 13 de 13 Legislación sobre obras Una instalación de telecomunicaciones en un hospital público se contrata, se ejecuta y se recibe con reglas que existen desde 1947. Conocerlas es parte del oficio. Obra pública Licitación Dirección de obra Representante técnico Reglamentación AEA 01 La obra pública La ley 13.064, de 1947, define la obra pública nacional como toda construcción, trabajo o servicio de industria que se ejecute con fondos del Tesoro de la Nación. Sigue vigente, con sus reglamentaciones, y cada provincia tiene su propia ley con una estructura parecida (en la provincia de Buenos Aires, la ley 6021). Una red de telecomunicaciones para un hospital…"},{"t":"Señales y fuentes de señal","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/senales-fuentes","x":"Electrónica Aplicada I · 120 h · Contenido 1 de 7 Señales y fuentes de señal Un micrófono de 600 Ω conectado a una entrada de 600 Ω pierde la mitad de su señal antes de que el amplificador haga nada. Elegir un amplificador empieza por mirar la fuente. Thévenin y Norton Decibeles Efecto de carga Impedancia de entrada Tipos de amplificador 01 La señal y su fuente Un amplificador nunca trabaja solo: toma la señal de una fuente —un micrófono, un sensor, una antena, la salida de otro circuito— y la entrega a una carga. Lo que hace bien o mal depende tanto de él como de esos dos extremos. Por eso el estudio de los amplificadores empieza por modelar la fuente. La descripción de las señales en el…"},{"t":"El transistor bipolar como amplificador: señal débil y fuerte","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/bjt-amplificador","x":"Electrónica Aplicada I · 120 h · Contenido 2 de 7 El transistor bipolar como amplificador: señal débil y fuerte Un emisor común sin degeneración es lineal solo para unos pocos milivolts: con 10 mV sobre la base ya produce casi un 10 % de segunda armónica. La escala del bipolar son 25,85 mV. Emisor común Degeneración de emisor Distorsión armónica Recorte Señal débil y fuerte 01 Señal débil y señal fuerte El transistor bipolar es un dispositivo exponencial: la corriente de colector sigue a la tensión base-emisor como . Ninguna exponencial es una recta, así que ningún amplificador con transistores es exactamente lineal. Lo que se hace es trabajar alrededor de un punto de reposo y separar dos…"},{"t":"El transistor de efecto de campo como amplificador: señal débil y fuerte","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/fet-amplificador","x":"Electrónica Aplicada I · 120 h · Contenido 3 de 7 El transistor de efecto de campo como amplificador: señal débil y fuerte La parábola del FET distorsiona solo en segunda armónica, y en una cantidad exacta: a igual entrada, casi ocho veces menos que un bipolar. El precio es amplificar menos por miliampere. Fuente común Transconductancia Sobreexcitación Segunda armónica Seguidor de fuente 01 Una ley cuadrática en lugar de una exponencial El transistor de efecto de campo —el MOS y el JFET— amplifica con la misma idea que el bipolar: una tensión de entrada controla una corriente de salida. La diferencia está en la forma de esa relación. En saturación, la corriente de drenador sigue una…"},{"t":"Fuentes de corriente y cargas activas","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/fuentes-corriente","x":"Electrónica Aplicada I · 120 h · Contenido 4 de 7 Fuentes de corriente y cargas activas Reemplazar una resistencia de colector por un transistor lleva la ganancia de una etapa de unos cientos a casi dos mil. Es el truco que hace posible un amplificador operacional. Espejo de corriente Fuente de Widlar Cascodo Resistencia de salida Carga activa 01 Transistores en lugar de resistencias En un circuito integrado las resistencias son caras —ocupan mucha área—, imprecisas —varían un 20 % de una oblea a otra— y no pueden ser muy grandes. Los transistores, en cambio, son baratos y, lo más importante, iguales entre sí: dos transistores vecinos de la misma oblea tienen parámetros casi idénticos. De…"},{"t":"El amplificador diferencial","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/amplificador-diferencial","x":"Electrónica Aplicada I · 120 h · Contenido 5 de 7 El amplificador diferencial El par diferencial no se satura de golpe: reparte una corriente fija entre dos lados. Por ser simétrico no genera segunda armónica, y por tener cola de corriente ignora lo que llega igual a las dos entradas. Par diferencial Modo común CMRR Tercera armónica Offset 01 El par diferencial Dos transistores iguales con los emisores unidos y alimentados por una fuente de corriente forman el circuito más importante de la electrónica analógica. La fuente fija la suma de las dos corrientes; lo único que la entrada puede hacer es repartirla entre los dos lados según la diferencia de tensión entre las bases, . Con la relación…"},{"t":"Amplificadores multietapa","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/amplificadores-multietapa","x":"Electrónica Aplicada I · 120 h · Contenido 6 de 7 Amplificadores multietapa Tres etapas iguales de 1 MHz no forman un amplificador de 1 MHz: la cascada corta a 510 kHz. Cada etapa agrega ganancia y se come ancho de banda. Cascada Efecto de carga Cascodo Efecto Miller Ancho de banda 01 Por qué más de una etapa Una sola etapa rara vez cumple todo lo que se pide de un amplificador: mucha ganancia, resistencia de entrada alta para no cargar a la fuente y resistencia de salida baja para excitar la carga. Cada configuración es buena en una cosa, así que se las combina en cascada, cada una haciendo lo suyo: Etapa Función Configuración típica Entrada No cargar a la fuente, rechazar el modo común,…"},{"t":"Diseño de circuitos integrados analógicos","d":"Tema · Electrónica Aplicada I","u":"/publicaciones/mapa-ingenieria/temas/diseno-ci-analogicos","x":"Electrónica Aplicada I · 120 h · Contenido 7 de 7 Diseño de circuitos integrados analógicos En un chip, ninguna resistencia vale lo que dice el plano, pero dos resistencias vecinas son casi idénticas. Todo el diseño analógico integrado se apoya en esa paradoja. Apareamiento Ley de Pelgrom Centroide común gm/ID Monte Carlo 01 Diseñar con cocientes El diseño analógico integrado parte de una paradoja. Los valores absolutos de un chip son malos: una resistencia puede salir un 20 % arriba o abajo de su valor, la tensión umbral de un transistor varía decenas de milivolts de una oblea a otra, y ninguna capacidad es exacta. Pero dos componentes iguales, dibujados juntos en el mismo chip, son casi…"},{"t":"Campos electromagnéticos para enlaces: Maxwell en la práctica","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/campos-maxwell","x":"Medios de Enlace · 96 h · Contenido 1 de 8 Campos electromagnéticos para enlaces: Maxwell en la práctica A 1 GHz la corriente de un cable de cobre circula en los primeros 2 micrones de su superficie, y la energía no viaja por el cobre sino por el aislante que lo rodea. Forma fasorial Condiciones de borde Efecto pelicular Resistencia de superficie Vector de Poynting 01 De la física al enlace Las ecuaciones de Maxwell ya aparecieron en Física II, en la página de las ecuaciones de Maxwell , como la síntesis de toda la electricidad y el magnetismo. En Medios de Enlace se las usa con un fin concreto: llevar una señal de un punto a otro, por el aire, por un cable, por una guía o por una fibra.…"},{"t":"Ecuaciones de onda y ondas planas","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/ondas-planas","x":"Medios de Enlace · 96 h · Contenido 2 de 8 Ecuaciones de onda y ondas planas El agua de mar refleja casi toda la onda de una radio de onda larga y se traga en pocos metros lo que entra. Por eso a un submarino sumergido solo le llegan frecuencias muy bajas. Constante de propagación Impedancia intrínseca Atenuación Reflexión Onda estacionaria 01 De Maxwell a la ecuación de onda Combinando las dos ecuaciones del rotor de la unidad anterior en una región sin fuentes, el campo eléctrico queda gobernado por una sola ecuación, la ecuación de Helmholtz: es la constante de propagación: su parte real es la atenuación, en nepers por metro, y su parte imaginaria , la constante de fase, en radianes por…"},{"t":"Guías de onda y modos","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/guias-onda","x":"Medios de Enlace · 96 h · Contenido 3 de 8 Guías de onda y modos Una guía de onda es un caño que no deja pasar las frecuencias bajas: una WR-90 bloquea todo lo que está por debajo de 6,56 GHz. Los agujeros de la puerta de un horno de microondas funcionan igual. Modo TE10 Frecuencia de corte Longitud de onda en la guía Velocidad de grupo Banda monomodo 01 Un caño que conduce ondas Por encima de unos pocos gigahertz, un cable coaxial empieza a perder mucho: el conductor central es delgado, el efecto pelicular concentra la corriente en su superficie y el dieléctrico absorbe. Para llevar potencia de microondas con pocas pérdidas se usa un tubo metálico hueco, la guía de onda. No tiene conductor…"},{"t":"Líneas de transmisión","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/lineas-transmision","x":"Medios de Enlace · 96 h · Contenido 4 de 8 Líneas de transmisión Un tramo de cable de un cuarto de onda convierte 100 Ω en 25 Ω sin un solo componente. A esas frecuencias, el largo del cable es parte del circuito. Impedancia característica Coeficiente de reflexión ROE Cuarto de onda Reflectometría 01 Cuándo un cable deja de ser un cable En la teoría de circuitos, un cable es un nodo: la tensión es la misma en sus dos extremos en el mismo instante. Eso vale mientras la señal tarde en recorrerlo mucho menos que lo que tarda en cambiar. Cuando el largo del cable se acerca a una fracción apreciable de la longitud de onda —la regla práctica es un décimo— o cuando el tiempo de subida de un pulso…"},{"t":"Potencia en líneas de transmisión","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/potencia-lineas","x":"Medios de Enlace · 96 h · Contenido 5 de 8 Potencia en líneas de transmisión Una antena con ROE 3 al final de 20 m de RG-58 se ve desde el transmisor con ROE 1,5. El equipo queda conforme, pero a la antena llega menos de un tercio de la potencia. Potencia incidente y reflejada Atenuación Pérdida por desadaptación ROE en el transmisor Potencia admisible 01 La potencia que viaja por la línea En una línea de transmisión la potencia viaja en dos ondas: la incidente, que va del generador a la carga, y la reflejada, que vuelve. Como la impedancia característica es real en una línea de pocas pérdidas, cada onda lleva su propia potencia y la que recibe la carga es la diferencia: Con amplitudes de…"},{"t":"Fibras ópticas y transmisión por fibra","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/fibras-opticas","x":"Medios de Enlace · 96 h · Contenido 6 de 8 Fibras ópticas y transmisión por fibra A 10 Gb/s, una fibra multimodo tiene potencia de sobra para 2 km, pero la dispersión corta el enlace en 300 m. En una monomodo, el mismo transmisor llega a decenas de kilómetros. Apertura numérica Monomodo y multimodo Ventanas Dispersión Balance del enlace 01 Luz por un hilo de vidrio Una fibra óptica es una guía de onda dieléctrica que trabaja a frecuencias de unos 200 THz. Tiene un núcleo de vidrio de sílice rodeado por un revestimiento de índice de refracción apenas menor, y la luz queda atrapada en el núcleo. Frente a un cable de cobre tiene tres ventajas decisivas: pierde 0,2 dB por kilómetro en lugar de…"},{"t":"Radiación electromagnética","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/radiacion-electromagnetica","x":"Medios de Enlace · 96 h · Contenido 7 de 8 Radiación electromagnética La antena de un metro de un auto tiene, en la banda de AM, una resistencia de radiación de milésimas de ohm. Un dipolo de media onda tiene 73 Ω y se conecta directo a un cable coaxial. Dipolo elemental Resistencia de radiación Directividad Diagrama de radiación Campo cercano 01 Por qué un conductor irradia Una carga en reposo crea un campo eléctrico; una carga en movimiento uniforme, además, uno magnético. Pero solo una carga acelerada desprende campos que se alejan por su cuenta y llevan energía hasta el infinito: eso es la radiación. En un conductor con corriente alterna los electrones aceleran y frenan todo el tiempo,…"},{"t":"Antenas y enlaces radioeléctricos","d":"Tema · Medios de Enlace","u":"/publicaciones/mapa-ingenieria/temas/antenas-enlace","x":"Medios de Enlace · 96 h · Contenido 8 de 8 Antenas y enlaces radioeléctricos Para un enlace de 30 km sobre terreno llano no alcanza con que las antenas se vean: en el centro, la Tierra sube 13 m y la zona de Fresnel mide 14 m de radio. Las torres necesitan unos 22 m. Ganancia Área efectiva Ecuación de Friis Zona de Fresnel Margen de desvanecimiento 01 Lo que define a una antena Una antena es el transductor entre una línea de transmisión y el espacio. La unidad de radiación dejó la resistencia de radiación, el diagrama y la directividad; para diseñar un enlace hacen falta además: Parámetro Qué dice Ganancia La directividad descontadas las pérdidas de la antena; se da en dBi Ancho del haz El…"},{"t":"Grupos nominales largos y oraciones complejas","d":"Tema · Inglés II","u":"/publicaciones/mapa-ingenieria/temas/linguistica-compleja","x":"Inglés II · 48 h · Contenido 1 de 3 Grupos nominales largos y oraciones complejas «Low-dropout linear voltage regulator» son cinco palabras y un solo sustantivo: el último. En castellano se lee al revés: regulador de tensión lineal de baja caída. Grupos nominales Nominalización compleja Pasiva con modales Cláusulas de participio Condicional invertida 01 Un escalón más arriba En Inglés I alcanzaba con reconocer la voz pasiva, una nominalización suelta, tres tiempos verbales y los conectores básicos. Los textos de tercer nivel —papers, notas de aplicación, normas— combinan esas mismas construcciones y las apilan: un sustantivo con cinco modificadores adelante, una pasiva con un modal y un…"},{"t":"El artículo científico y la prominencia textual","d":"Tema · Inglés II","u":"/publicaciones/mapa-ingenieria/temas/textos-cientificos","x":"Inglés II · 48 h · Contenido 2 de 3 El artículo científico y la prominencia textual «These results suggest» y «these results demonstrate» dicen cosas muy distintas sobre cuánto confían los autores. Leer un paper es también leer esa diferencia. IMRyD Movidas retóricas Tema y rema Atenuación y refuerzo Encapsuladores 01 Los géneros que lee un ingeniero En Inglés I los géneros eran profesionales: la hoja de datos, el manual, la norma. En los niveles superiores de la carrera y en el trabajo de investigación aparecen los géneros académico-científicos, más densos y con una estructura retórica que conviene conocer antes de leer: Género Propósito Cómo se lo reconoce Artículo de revista (journal…"},{"t":"Paráfrasis, sustitución y circunloquio","d":"Tema · Inglés II","u":"/publicaciones/mapa-ingenieria/temas/estrategias-parafrasis","x":"Inglés II · 48 h · Contenido 3 de 3 Paráfrasis, sustitución y circunloquio Si no aparece la palabra «capacitor», «the part that stores charge between two plates» cumple la misma función. El circunloquio es una estrategia legítima, no un fracaso. Paráfrasis Sustitución Circunloquio Presentación oral Citas 01 Producir con lo que se tiene Leer un texto técnico en inglés es la habilidad central de la materia, pero en algún momento hay que producir: resumir un artículo para un informe, escribir un correo a un fabricante, explicar un circuito en una reunión. Ahí aparece un problema distinto al de la lectura: falta la palabra justa. La dimensión estratégica es el conjunto de recursos para…"},{"t":"Conversores analógico-digitales y digital-analógicos","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/conversores-datos","x":"Técnicas Digitales II · 120 h · Contenido 1 de 6 Conversores analógico-digitales y digital-analógicos Un conversor de 14 bits que muestrea una señal de 49 MHz con un reloj de 1 ps de jitter rinde lo mismo que uno de 11 bits: el reloj, no el conversor, pone el límite. Cuantización ENOB INL y DNL Jitter SAR y sigma-delta 01 La frontera entre lo analógico y lo digital Todo sistema digital que mide o actúa sobre el mundo tiene un conversor en cada borde: un conversor analógico-digital (ADC) que convierte una tensión en un número, y uno digital-analógico (DAC) que hace lo inverso. Entre los dos puede haber el procesamiento más sofisticado, pero la calidad del sistema nunca supera la de sus…"},{"t":"Memorias electrónicas","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/memorias-electronicas","x":"Técnicas Digitales II · 120 h · Contenido 2 de 6 Memorias electrónicas Un módulo de memoria de servidor tiene 72 bits de ancho para guardar 64: los ocho restantes corrigen cualquier bit que invierta un rayo cósmico. SRAM y DRAM Flash NOR y NAND Mapa de memoria Desgaste Código de Hamming 01 Qué distingue a una memoria de otra Una memoria guarda bits en celdas, y cada tecnología guarda el bit de una forma física distinta: el estado de un biestable, la carga de un capacitor, la carga atrapada en una compuerta aislada o la polarización de un material. De esa forma física salen todas sus propiedades: si pierde el dato al cortar la alimentación, cuánto tarda en leer y escribir, cuántas veces se…"},{"t":"Arquitecturas y organización de procesadores","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/arquitectura-procesadores","x":"Técnicas Digitales II · 120 h · Contenido 3 de 6 Arquitecturas y organización de procesadores Sumar una matriz recorriéndola por columnas en lugar de por filas puede bajar la tasa de aciertos de la caché del 87 % al 0 %. El algoritmo es el mismo; lo que cambia es el orden. RISC y CISC CPI Pipeline Caché Localidad 01 Arquitectura y organización Hay dos maneras de mirar un procesador. La arquitectura es el contrato con el software: el conjunto de instrucciones, los registros visibles, los modos de direccionamiento, el modelo de memoria. La organización (o microarquitectura) es cómo se cumple ese contrato en el silicio: cuántas etapas tiene el pipeline, qué cachés hay, cuántas instrucciones se…"},{"t":"Hardware y software de sistemas embebidos","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/sistemas-embebidos","x":"Técnicas Digitales II · 120 h · Contenido 4 de 6 Hardware y software de sistemas embebidos Un sensor que duerme a 2 µA dura más de dos años con una pila CR2032. Si un periférico queda encendido y el reposo sube a 50 µA, la misma pila dura cuatro meses. Microcontrolador Código de arranque Interrupciones Bajo consumo Watchdog 01 Una computadora que nadie ve Un sistema embebido es una computadora dedicada a una tarea dentro de un producto: el control de un lavarropas, la unidad de un airbag, un medidor de gas, un marcapasos. No se ve como computadora y casi nunca se reprograma, pero tiene procesador, memoria, periféricos y software. Lo que lo distingue es el conjunto de restricciones: costo…"},{"t":"Comunicaciones y protocolos seriales","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/protocolos-seriales","x":"Técnicas Digitales II · 120 h · Contenido 5 de 6 Comunicaciones y protocolos seriales Una trama CAN lleva a lo sumo 8 bytes de datos y 47 bits de control. Por eso, aun a 1 Mbit/s, el bus de un auto no transporta más de unos 72 kB/s de datos útiles. UART SPI I²C CAN Codificación de línea 01 Por qué casi todo es serie Durante décadas los datos viajaron en paralelo: ocho, dieciséis o treinta y dos líneas a la vez. A alta velocidad eso deja de funcionar: los bits de un mismo dato llegan con diferencias de tiempo por las distintas longitudes de las pistas, y cada línea que conmuta agrega ruido a las vecinas. Una sola línea diferencial, bien adaptada, llega hoy a decenas de gigabits por segundo.…"},{"t":"Sistemas operativos en tiempo real","d":"Tema · Técnicas Digitales II","u":"/publicaciones/mapa-ingenieria/temas/rtos","x":"Técnicas Digitales II · 120 h · Contenido 6 de 6 Sistemas operativos en tiempo real Con una utilización del 95 %, tres tareas pueden perder un plazo con prioridades fijas y cumplir todos con EDF. La diferencia no es la potencia del procesador sino el orden en que se atienden. Tareas Planificación RM EDF Tiempo de respuesta Inversión de prioridad 01 Tiempo real no quiere decir rápido Un sistema es de tiempo real cuando la corrección de un resultado depende también de cuándo se entrega. El control de un airbag que calcula perfecto pero 50 ms tarde falló. Lo que importa no es la velocidad promedio sino el peor caso: la garantía de que cada tarea termina antes de su plazo, siempre. Se…"},{"t":"Errores, incertidumbre y exactitud de los instrumentos","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/errores-incertidumbre","x":"Medidas Electrónicas I · 120 h · Contenido 1 de 11 Errores, incertidumbre y exactitud de los instrumentos Medir 5 V en la escala de 200 V de un multímetro en lugar de la de 20 V multiplica la incertidumbre por seis. El instrumento es el mismo; la decisión es de quien mide. Error sistemático Tipo A y tipo B Incertidumbre expandida Especificación Trazabilidad 01 Ninguna medición es exacta Medir es comparar una magnitud con una referencia, y ninguna comparación es perfecta. El valor que da un instrumento difiere del verdadero por el instrumento, por el método, por el ambiente y por quien mide. Lo que distingue a una medición de ingeniería no es que no tenga error, sino que dice cuánto puede…"},{"t":"Tensión, corriente y potencia en baja frecuencia","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/mediciones-baja-frecuencia","x":"Medidas Electrónicas I · 120 h · Contenido 2 de 11 Tensión, corriente y potencia en baja frecuencia Un voltímetro analógico de 20 kΩ/V que mide un divisor de 100 kΩ lee 4 V donde hay 5. No está descalibrado: al conectarse, cambió el circuito. Efecto de carga Tensión de carga Vatímetro Método de Aron Pinza amperométrica 01 Todo instrumento modifica lo que mide Para medir una tensión, el voltímetro se conecta en paralelo y toma algo de corriente; para medir una corriente, el amperímetro se intercala en serie y agrega resistencia. En los dos casos el circuito cambia al conectar el instrumento, y lo que se mide es el circuito modificado. Ese efecto de carga es un error sistemático que se puede…"},{"t":"Fuentes de señales","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/fuentes-senales","x":"Medidas Electrónicas I · 120 h · Contenido 3 de 11 Fuentes de señales Un DDS con reloj de 100 MHz ajusta la frecuencia en pasos de 0,023 Hz, pero a 45 MHz su imagen queda casi al mismo nivel que la señal. Por eso nadie lo usa más allá del 40 % de su reloj. Generador de funciones DDS Palabra de sintonía Imágenes Salida de 50 Ω 01 La mitad de cada medición Para medir la respuesta de un amplificador, un filtro o un receptor hace falta excitarlo con una señal conocida. La fuente de señales es la otra mitad del banco de medición, y sus imperfecciones —distorsión, error de frecuencia, ruido de fase, amplitud que cambia con la frecuencia— se suman a las del circuito que se ensaya. Conocer cómo se…"},{"t":"Medición de señales no senoidales","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/senales-no-senoidales","x":"Medidas Electrónicas I · 120 h · Contenido 4 de 11 Medición de señales no senoidales Un multímetro que no es true RMS lee una onda cuadrada un 11 % de más y un tren de pulsos del 10 % un tercio de menos. Con la senoidal, la única forma para la que está calibrado, acierta. Valor eficaz Factor de forma Factor de cresta True RMS Ancho de banda 01 Tres valores para una misma señal De una tensión periódica se pueden medir varias cosas, y cada una responde a una pregunta distinta: El valor medio es la componente continua; el valor medio rectificado, el promedio del valor absoluto; el valor eficaz, la tensión continua que disiparía la misma potencia en un resistor. Solo este último tiene sentido…"},{"t":"Puentes y medición de componentes","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/puentes-qmetro","x":"Medidas Electrónicas I · 120 h · Contenido 5 de 11 Puentes y medición de componentes En el equilibrio de un puente no circula corriente por el detector, así que el resultado no depende del detector ni de la fuente: solo de los componentes de referencia. Wheatstone Kelvin Maxwell Q-metro Cuatro terminales 01 Medir por comparación Un puente mide un componente comparándolo con otros conocidos. En lugar de leer una tensión en un instrumento, se ajustan los componentes conocidos hasta que un detector marca cero. En ese equilibrio no circula corriente por el detector y el resultado no depende de su exactitud ni de la de la fuente: solo de los componentes de referencia. Por eso los puentes fueron…"},{"t":"El osciloscopio analógico","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/osciloscopio-analogico","x":"Medidas Electrónicas I · 120 h · Contenido 6 de 11 El osciloscopio analógico Una punta 10:1 mal compensada hace que la cuadrada del calibrador arranque en 3,7 V en lugar de 5 V. El trimmer de la punta no es un detalle: decide si la amplitud medida es correcta. Tubo de rayos catódicos Ancho de banda Tiempo de subida Disparo Punta compensada 01 Ver la forma de una señal El osciloscopio dibuja la tensión en función del tiempo. Ningún otro instrumento muestra de un vistazo la forma, los picos, las oscilaciones, los tiempos de subida y los transitorios. Hoy casi todos los osciloscopios son digitales, pero su canal vertical, su disparo y sus puntas heredan la arquitectura del analógico, y…"},{"t":"El osciloscopio digital","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/osciloscopio-digital","x":"Medidas Electrónicas I · 120 h · Contenido 7 de 11 El osciloscopio digital Un osciloscopio de 1 GS/s con 1000 puntos de memoria, en 10 µs/div, muestrea a solo 10 MS/s. Una señal de 10,1 MHz aparece entonces como una senoidal limpia de 100 kHz que no existe. Frecuencia de muestreo Memoria Alias Detección de picos Resolución vertical 01 Del haz a la memoria Un osciloscopio digital de almacenamiento (DSO) conserva el canal vertical del analógico —atenuador, amplificador, ancho de banda— pero en lugar de desviar un haz, digitaliza la señal con un ADC rápido y guarda las muestras en una memoria de adquisición. El disparo decide qué parte de esa memoria se muestra, y un procesador arma la imagen,…"},{"t":"Acondicionamiento de señales y sensores","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/acondicionamiento-sensores","x":"Medidas Electrónicas I · 120 h · Contenido 8 de 11 Acondicionamiento de señales y sensores Un Pt100 conectado a dos hilos con 10 m de cable fino mide 4,5 °C de más. El sensor es exacto; el error lo ponen los cables. Pt100 Termocupla Galgas Amplificador de instrumentación Cuatro hilos 01 Del fenómeno al número Para medir una temperatura, una fuerza o una presión, un sensor convierte la magnitud en una señal eléctrica: una resistencia que cambia, una tensión de microvolts, una corriente. Casi nunca esa señal se puede conectar directo al conversor. El acondicionamiento es todo lo que hay entre los dos: excitar el sensor, amplificar, filtrar, aislar, compensar y linealizar. Los errores de esa…"},{"t":"Interferencias de modo normal y de modo común","d":"Tema · Medidas Electrónicas I","u":"/publicaciones/mapa-ingenieria/temas/interferencias-medicion","x":"Medidas Electrónicas I · 120 h · Contenido 9 de 11 Interferencias de modo normal y de modo común Un amplificador de 120 dB de rechazo de modo común no sirve de nada si una de las líneas tiene 10 kΩ más que la otra: el desbalance convierte el modo común en señal antes de llegar a la entrada. Modo común Modo normal Lazos de masa CMRR Integración 01 Dos maneras de meterse en una medición Una interferencia es cualquier tensión que se suma a la que se quiere medir. Según cómo aparece en los terminales del instrumento, se distinguen dos modos: Modo normal (o diferencial): la interferencia está en serie con la señal, entre los dos terminales de entrada. El instrumento no tiene forma de separarla…"},{"t":"La carta de Smith","d":"Publicación","u":"/publicaciones/carta-smith","x":"🧭 La carta de Smith Una sola hoja para leer impedancias, sacar el coeficiente de reflexión y la ROE, ver qué le hace a una carga un tramo de línea y diseñar la adaptación, sin resolver una ecuación compleja por paso. Medios de Enlace · Ingeniería Electrónica · En el programa figura como «el ábaco de Smith y su uso». Línea sin pérdidas. El plano de Γ con una grilla de impedancias encima La carta es el círculo de radio 1 del coeficiente de reflexión Γ. Cada punto adentro es una carga posible. Encima se dibuja la grilla que dice qué impedancia corresponde a ese Γ: círculos de resistencia constante y arcos de reactancia constante. Pasá el cursor por la carta: se resaltan el círculo y el arco…"}]);
